-- =====================================================================
-- migracje/013_czas_i_resynchronizacje.sql
-- =====================================================================

-- Czas świata płynie 1:1 z czasem rzeczywistym. MG może skrócić albo wydłużyć pojedynczy proces
-- (skok floty, podróż, obsługa naziemna) — w grze nazywa się to resynchronizacją (ingerencją mocy).
-- Gra nie tłumaczy graczom, co się stało; ten dziennik widzi tylko MG.
-- Wymaga migracji 012 i tabeli schema_migracje. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz; ponowny import zatrzyma się na „Duplicate column”.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS resynchronizacje (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  rodzaj ENUM('skok_floty','podroz','obsluga_statku') NOT NULL,
  obiekt VARCHAR(120) NOT NULL COMMENT 'np. id rozkazu skoku, uid postaci, f:<firma>:<statek>',
  opis VARCHAR(255) NOT NULL DEFAULT '' COMMENT 'czytelna nazwa procesu w chwili ingerencji',
  koniec_przed_utc DATETIME NOT NULL,
  koniec_po_utc DATETIME NOT NULL,
  mg_login VARCHAR(64) NOT NULL,
  notatka VARCHAR(500) NOT NULL DEFAULT '',
  utworzono_utc DATETIME NOT NULL,
  KEY ix_resynchronizacje_obiekt (rodzaj, obiekt),
  KEY ix_resynchronizacje_czas (utworzono_utc)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Zegar świata: 1 sekunda rzeczywista = 1 sekunda świata (60 s na minutę świata).
UPDATE zegar_swiata SET sekund_na_minute_gst = 60.000 WHERE id = 1;

VALUES ('v13-czas-resynchronizacje', 'Czas świata 1:1 i dziennik resynchronizacji procesów przez MG')
ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- =====================================================================
-- migracje/014_skoki_statkow_i_radar.sql
-- =====================================================================

-- Skok statku postaci z wyliczanym czasem (resynchronizowalny) i radarowe wykrywanie skoków.
-- Wymaga migracji 013. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz; ponowny import zatrzyma się na „Duplicate column”.

SET NAMES utf8mb4;

-- Resynchronizacja obejmuje teraz także skok statku postaci.
ALTER TABLE resynchronizacje
  MODIFY rodzaj ENUM('skok_floty','podroz','obsluga_statku','skok_statku') NOT NULL;

-- Wykrycia skoków przez jednostki na mapie (warstwa mapa_*). Szacunek z błędem: punkt wyjścia
-- z marginesem w pc i szacowany czas przylotu. Docelowy model sensorów to wykrycia_nadprzestrzenne
-- (jednostki_floty); ta tabela obsługuje jednostki mapy, dopóki obie warstwy się nie połączą.
CREATE TABLE IF NOT EXISTS mapa_wykrycia_skokow (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  obiekt_id BIGINT UNSIGNED NOT NULL COMMENT 'jednostka, która wykryła skok',
  cel_rodzaj ENUM('statek_postaci','flota') NOT NULL,
  cel_klucz VARCHAR(120) NOT NULL COMMENT 's:<firma>:<statek> albo id rozkazu skoku floty',
  cel_nazwa VARCHAR(160) NOT NULL DEFAULT '' COMMENT 'jak radar opisuje cel (transponder albo sygnatura)',
  start_x DECIMAL(12,1) NOT NULL,
  start_y DECIMAL(12,1) NOT NULL,
  szac_x DECIMAL(12,1) NOT NULL,
  szac_y DECIMAL(12,1) NOT NULL,
  margines_pc DECIMAL(12,2) NOT NULL DEFAULT 0,
  szac_eta_utc DATETIME NOT NULL,
  wiarygodnosc TINYINT UNSIGNED NOT NULL DEFAULT 5 CHECK (wiarygodnosc BETWEEN 1 AND 10),
  wykryto_utc DATETIME NOT NULL,
  KEY ix_mapa_wykrycia_obiekt (obiekt_id, szac_eta_utc),
  KEY ix_mapa_wykrycia_cel (cel_rodzaj, cel_klucz),
  FOREIGN KEY (obiekt_id) REFERENCES mapa_obiekty (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

VALUES ('v14-skoki-statkow-radar', 'Czas skoku statku postaci, resynchronizacja skoku i radarowe wykrywanie skoków')
ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- =====================================================================
-- migracje/015_kurs_manewry_i_cykle_planet.sql
-- =====================================================================

-- Kurs jednostek, manewr przed skokiem, cykle planet (doba, rok, pory roku) i księżyce.
--
-- KURS: kurs_deg to kierunek dziobu w nieruchomym układzie mapy (0° = wschód, 90° = północ,
-- przeciwnie do ruchu wskazówek zegara). Na orbicie ten sam kąt mówi, po której stronie planety
-- stoi jednostka (dziób od planety, rufa ku planecie). Manewr to płynna zmiana kursu (i miejsca
-- na orbicie) od kurs_start_deg do kurs_cel_deg w czasie manewr_od_utc → manewr_do_utc.
--
-- CYKLE PLANET: epoka 0 = 1|1|0 00:00 (1.01.2010 00:00 czasu polskiego). Planeta bez wiersza
-- w planety_cykle dostaje powtarzalne wartości domyślne wyliczane z nazwy (api/astro.php).
-- NULL w kolumnie = wartość domyślna. Księżyce z planety_ksiezyce zastępują wygenerowane.
-- Docelowy, pełny model orbit (uklady_planetarne, planety_orbity) pozostaje fundamentem.
--
-- Wymaga migracji 014. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz; ponowny import zatrzyma się na „Duplicate column”.

SET NAMES utf8mb4;

-- ---------- kurs i manewr jednostek mapy ----------

ALTER TABLE mapa_obiekty
  ADD COLUMN kurs_deg DECIMAL(6,2) NOT NULL DEFAULT 90 AFTER y,
  ADD COLUMN kurs_start_deg DECIMAL(6,2) NULL AFTER kurs_deg,
  ADD COLUMN kurs_cel_deg DECIMAL(6,2) NULL AFTER kurs_start_deg,
  ADD COLUMN manewr_od_utc DATETIME NULL AFTER kurs_cel_deg,
  ADD COLUMN manewr_do_utc DATETIME NULL AFTER manewr_od_utc;

-- Tempo obrotu (i przelotu po orbicie) w stopniach na minutę; flota manewruje tempem najwolniejszej jednostki.
ALTER TABLE mapa_naped_jednostki
  ADD COLUMN obrot_deg_na_min DECIMAL(6,2) NOT NULL DEFAULT 90 AFTER szum_bazowy;

-- Domyślne tempa według klasy (tylko tam, gdzie wciąż jest wartość domyślna).
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
  SET n.obrot_deg_na_min = 30
  WHERE n.obrot_deg_na_min = 90 AND (o.klasa LIKE '%Imperial%' OR o.klasa LIKE '%ISD%' OR o.nazwa LIKE 'ISD%');
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
  SET n.obrot_deg_na_min = 60
  WHERE n.obrot_deg_na_min = 90 AND (o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%');

-- Rozkaz skoku: chwila wejścia w nadprzestrzeń (po manewrze) i kurs skoku.
ALTER TABLE mapa_rozkazy_skokow
  ADD COLUMN wejscie_utc DATETIME NULL AFTER wydano_utc,
  ADD COLUMN kurs_deg DECIMAL(6,2) NULL AFTER cel_y;

-- Resynchronizacja obejmuje też manewry (zmiana kursu / pozycji na orbicie).
ALTER TABLE resynchronizacje
  MODIFY rodzaj ENUM('skok_floty','podroz','obsluga_statku','skok_statku','manewr') NOT NULL;

-- Wykrycie radarowe może dotyczyć skoku, który zacznie się po manewrze (widoczne od wykryto_utc).

-- ---------- cykle planet i księżyce ----------

CREATE TABLE IF NOT EXISTS planety_cykle (
  planeta_id INT UNSIGNED NOT NULL PRIMARY KEY,
  doba_h DECIMAL(10,4) NULL COMMENT 'doba słoneczna w godzinach (NULL = z mapa_planety.doba)',
  rok_dni DECIMAL(12,4) NULL COMMENT 'rok w dniach (NULL = z mapa_planety.rok)',
  nachylenie_osi_deg DECIMAL(6,3) NULL COMMENT 'nachylenie osi: amplituda pór roku',
  faza_obrotu_deg DECIMAL(7,3) NULL COMMENT 'kąt godzinny południka 0 w epoce (0 = południe, 180 = północ)',
  faza_roku_deg DECIMAL(7,3) NULL COMMENT 'faza pór roku w epoce: deklinacja = nachylenie · sin(360·d/rok + faza)',
  faza_orbity_deg DECIMAL(7,3) NULL COMMENT 'położenie planety wokół słońca w epoce (układ mapy)',
  promien_orbity_au DECIMAL(10,4) NULL COMMENT 'promień orbity wokół słońca (widok układu)',
  srednica_km DECIMAL(12,2) NULL COMMENT 'średnica (NULL = z mapa_planety.srednica)',
  FOREIGN KEY (planeta_id) REFERENCES mapa_planety (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS planety_ksiezyce (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  planeta_id INT UNSIGNED NOT NULL,
  nazwa VARCHAR(120) NOT NULL,
  promien_orbity_km DECIMAL(14,1) NOT NULL CHECK (promien_orbity_km > 0),
  okres_dni DECIMAL(12,4) NOT NULL CHECK (okres_dni > 0) COMMENT 'obieg gwiazdowy wokół planety',
  faza_deg DECIMAL(7,3) NOT NULL DEFAULT 0 COMMENT 'położenie w epoce (układ mapy)',
  srednica_km DECIMAL(12,2) NULL,
  UNIQUE KEY uq_planety_ksiezyce (planeta_id, nazwa),
  FOREIGN KEY (planeta_id) REFERENCES mapa_planety (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Zephyria = Ziemia: doba 24 h, rok zwrotnikowy, nachylenie 23,44°. Faza obrotu: epoka to
-- 31.12.2009 23:00 UTC, czyli 23:00 czasu słonecznego na południku 0 → kąt godzinny 165°.
-- Pory roku: przesilenie zimowe ok. 10,5 dnia przed epoką → faza 280,35°.
-- Pełnia księżyca 31.12.2009 → księżyc po stronie przeciwnej słońcu (faza = faza orbity).
                           faza_orbity_deg, promien_orbity_au, srednica_km)
SELECT id, 24, 365.2422, 23.44, 165, 280.35, 100, 1, 12742 FROM mapa_planety WHERE nazwa = 'Zephyria'
ON DUPLICATE KEY UPDATE doba_h = VALUES(doba_h), rok_dni = VALUES(rok_dni), nachylenie_osi_deg = VALUES(nachylenie_osi_deg),
  faza_obrotu_deg = VALUES(faza_obrotu_deg), faza_roku_deg = VALUES(faza_roku_deg), faza_orbity_deg = VALUES(faza_orbity_deg),
  promien_orbity_au = VALUES(promien_orbity_au), srednica_km = VALUES(srednica_km);

SELECT id, 'Księżyc', 384400, 27.3217, 100, 3474.8 FROM mapa_planety WHERE nazwa = 'Zephyria'
ON DUPLICATE KEY UPDATE promien_orbity_km = VALUES(promien_orbity_km), okres_dni = VALUES(okres_dni),
  faza_deg = VALUES(faza_deg), srednica_km = VALUES(srednica_km);

VALUES ('v15-kurs-manewry-cykle', 'Kurs i manewry jednostek, wejście w skok po manewrze, cykle planet i księżyce')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/016_orbita_przylot_rozbicie.sql
-- =====================================================================

-- Miejsce na orbicie osobno od kursu, chwila przylotu (faza podejścia) i rozbicie okrętu.
--
-- orbita_deg: po której stronie planety stoi jednostka (układ mapy: 0° = wschód, 90° = północ);
--             od tego zależy dzień/noc pod okrętem i czy wisi między planetą a księżycem.
-- kurs_deg:   kierunek dziobu, niezależny od miejsca na orbicie (widok z mostka, strzałka na mapie).
-- przylot_utc: wyjście z nadprzestrzeni przy planecie; z niego wynika podejście (planeta w oknie
--             najpierw mała, potem średnia, na orbicie duża).
-- rozbity:    okręt rozbity na planecie (ustawia MG); z mostka widać powierzchnię.
--
-- Wymaga migracji 015. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz; ponowny import zatrzyma się na „Duplicate column”.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN orbita_deg DECIMAL(6,2) NULL AFTER kurs_deg,
  ADD COLUMN przylot_utc DATETIME NULL AFTER manewr_do_utc,
  ADD COLUMN rozbity TINYINT(1) NOT NULL DEFAULT 0 AFTER przylot_utc;

-- Dotąd kurs na orbicie oznaczał stronę planety (dziobem od planety). Przenosimy go do orbita_deg,
-- a dziób kierujemy ku planecie — z mostka widać planetę.
UPDATE mapa_obiekty
  SET orbita_deg = kurs_deg,
      kurs_deg = MOD(kurs_deg + 180, 360)
  WHERE orbita_deg IS NULL AND planeta_id IS NOT NULL AND typ IN ('statek', 'jednostka');

VALUES ('v16-orbita-przylot-rozbicie', 'Miejsce na orbicie osobno od kursu, faza podejścia po skoku, rozbicie okrętu')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/017_komputer_nawigacyjny_i_dolot.sql
-- =====================================================================

-- Komputer nawigacyjny okrętu, warianty celu skoku (orbita bliska/średnia/daleka, krawędź układu)
-- i dolot na orbitę napędem podświetlnym.
--
-- komputer_klasa (1–5): jakość automatu; im wyższa, tym mniejszy rozrzut wyjścia z nadprzestrzeni.
-- komputer_stan: sprawny | zhakowany (automat działa, ale po cichu podaje zły wynik) |
--                przejety | brak (automatu nie ma: mostek liczy sam, ręczne współrzędne,
--                dłuższe obliczenia przed manewrem, większy rozrzut).
-- podejscie: gdzie w układzie jest okręt po wyjściu ze skoku: bliska / srednia / daleka orbita
--            albo krawedz układu. Dolot (podlot_*) zmienia go napędem podświetlnym, z czasem.
--
-- Wymaga migracji 016. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz; ponowny import zatrzyma się na „Duplicate column”.

SET NAMES utf8mb4;

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN komputer_klasa TINYINT UNSIGNED NOT NULL DEFAULT 3 AFTER obrot_deg_na_min,
  ADD COLUMN komputer_stan ENUM('sprawny','zhakowany','przejety','brak') NOT NULL DEFAULT 'sprawny' AFTER komputer_klasa;

-- ISD: fachowy, wydajny komputer (5); Arquitens 4; reszta 3 (tylko tam, gdzie wartość domyślna).
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
  SET n.komputer_klasa = 5
  WHERE n.komputer_klasa = 3 AND (o.klasa LIKE '%Imperial%' OR o.klasa LIKE '%ISD%' OR o.nazwa LIKE 'ISD%');
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
  SET n.komputer_klasa = 4
  WHERE n.komputer_klasa = 3 AND (o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%');

ALTER TABLE mapa_obiekty
  ADD COLUMN podejscie ENUM('bliska','srednia','daleka','krawedz') NULL AFTER przylot_utc,
  ADD COLUMN podlot_start ENUM('bliska','srednia','daleka','krawedz') NULL AFTER podejscie,
  ADD COLUMN podlot_cel ENUM('bliska','srednia','daleka','krawedz') NULL AFTER podlot_start,
  ADD COLUMN podlot_od_utc DATETIME NULL AFTER podlot_cel,
  ADD COLUMN podlot_do_utc DATETIME NULL AFTER podlot_od_utc;

ALTER TABLE mapa_rozkazy_skokow
  ADD COLUMN wariant ENUM('bliska','srednia','daleka','krawedz') NULL AFTER kurs_deg,
  ADD COLUMN tryb ENUM('automat','reczny') NOT NULL DEFAULT 'automat' AFTER wariant;

-- Okręty już stojące przy planecie są na bliskiej orbicie.
UPDATE mapa_obiekty SET podejscie = 'bliska'
  WHERE podejscie IS NULL AND planeta_id IS NOT NULL AND typ IN ('statek', 'jednostka');

ALTER TABLE resynchronizacje
  MODIFY rodzaj ENUM('skok_floty','podroz','obsluga_statku','skok_statku','manewr','dolot') NOT NULL;

VALUES ('v17-komputer-nawigacyjny-dolot', 'Komputer nawigacyjny, warianty celu skoku, dolot na orbitę')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

