-- =====================================================================
-- migracje/023_b0r5_scalenie_frachtowce.sql
-- =====================================================================

-- B0R5: scalenie trzech firm o tej samej nazwie w jedną i frachtowce dla agentów.
--
-- W dokumencie `firmy` (datapad_dane) były trzy firmy B0R5:
--   b23ff14eabfb — z właścicielem (konto c28783b95807), bez budynków  → ZOSTAJE
--   473b397d017a, 3786a2f49d03 — bez członków, kopie „Bazy B0R5” na Zephyrii (saldo 0) → USUNIĘTE
-- Baza B0R5 trafia do firmy z właścicielem (z poprawnymi współrzędnymi zamiast „Array”), obok niej
-- ukryta platforma lądowania, a na niej trzy frachtowce z transponderami-przykrywkami.
-- Przed zmianą kopia dokumentu: datapad_dane.nazwa = 'firmy_kopia_przed_023'.
--
-- Wymaga migracji 022. Import w phpMyAdmin: zakładka SQL albo Import. Ponowny import niczego
-- nie dubluje (dopisanie tylko, gdy frachtowców jeszcze nie ma).

SET NAMES utf8mb4;

-- kopia bezpieczeństwa
SELECT 'firmy_kopia_przed_023', payload FROM datapad_dane WHERE nazwa = 'firmy'
ON DUPLICATE KEY UPDATE payload = payload;

-- ścieżka firmy z właścicielem, np. $.firmy[4]
SET @sciezka := JSON_UNQUOTE(JSON_SEARCH((SELECT payload FROM datapad_dane WHERE nazwa = 'firmy'), 'one', 'b23ff14eabfb', NULL, '$.firmy[*].id'));
SET @firma := SUBSTRING(@sciezka, 1, CHAR_LENGTH(@sciezka) - 3);

UPDATE datapad_dane SET payload = JSON_ARRAY_APPEND(payload,
  CONCAT(@firma, '.dane.budynki'), CAST('{"id": "4762df3763fa", "typ": "baza", "nazwa": "Baza B0R5", "opis": "Tajny kompleks operacyjny B0R5. Serwerownia, biuro, antena komunikacyjna, odbiornik Holonetu, garaż i magazyn.", "planeta": "73be99b5dcfe", "x": 12.4, "y": -6.3, "wspolrzedne": "", "powierzchnia": 800, "pietra": 1, "szyby": 1, "pojemnosc": 0, "pracownicy": 0, "pensja": 0, "menedzer": ""}' AS JSON),
  CONCAT(@firma, '.dane.budynki'), CAST('{"id": "b0r5ab000002", "typ": "platforma", "nazwa": "Platforma lądowania B0R5", "opis": "Ukryta platforma przy bazie B0R5, osłonięta skałami.", "planeta": "73be99b5dcfe", "x": 12.6, "y": -6.5, "wspolrzedne": "", "jakosc": 4, "paliwo": 100, "powierzchnia": 1200, "pietra": 0, "szyby": 0, "pojemnosc": 3, "pracownicy": 0, "pensja": 0, "menedzer": ""}' AS JSON),
  CONCAT(@firma, '.dane.flota'), CAST('{"id": "b0r5f0000001", "nazwa": "Wędrowny Kupiec", "klasa": "YT-2400", "transponder": "Wędrowny Kupiec", "stan": "sprawny", "hangar": "b:b23ff14eabfb:b0r5ab000002", "paliwo": 100, "kapitan": "", "ladownosc": 150, "hipernaped": 2, "lokalizacja": "73be99b5dcfe"}' AS JSON),
  CONCAT(@firma, '.dane.flota'), CAST('{"id": "b0r5f0000002", "nazwa": "Złota Plewa", "klasa": "Ghtroc 720", "transponder": "Złota Plewa", "stan": "sprawny", "hangar": "b:b23ff14eabfb:b0r5ab000002", "paliwo": 100, "kapitan": "", "ladownosc": 135, "hipernaped": 2, "lokalizacja": "73be99b5dcfe"}' AS JSON),
  CONCAT(@firma, '.dane.flota'), CAST('{"id": "b0r5f0000003", "nazwa": "Cicha Rzeka", "klasa": "Ghtroc 720", "transponder": "Cicha Rzeka", "stan": "sprawny", "hangar": "b:b23ff14eabfb:b0r5ab000002", "paliwo": 100, "kapitan": "", "ladownosc": 135, "hipernaped": 2, "lokalizacja": "73be99b5dcfe"}' AS JSON))
WHERE nazwa = 'firmy' AND @firma IS NOT NULL AND JSON_SEARCH(payload, 'one', 'b0r5f0000001') IS NULL;

-- usunięcie pustych kopii (każda ścieżka liczona na nowo, bo indeksy się przesuwają)
SET @sciezka := JSON_UNQUOTE(JSON_SEARCH((SELECT payload FROM datapad_dane WHERE nazwa = 'firmy'), 'one', '473b397d017a', NULL, '$.firmy[*].id'));
UPDATE datapad_dane SET payload = JSON_REMOVE(payload, SUBSTRING(@sciezka, 1, CHAR_LENGTH(@sciezka) - 3))
WHERE nazwa = 'firmy' AND @sciezka IS NOT NULL;

SET @sciezka := JSON_UNQUOTE(JSON_SEARCH((SELECT payload FROM datapad_dane WHERE nazwa = 'firmy'), 'one', '3786a2f49d03', NULL, '$.firmy[*].id'));
UPDATE datapad_dane SET payload = JSON_REMOVE(payload, SUBSTRING(@sciezka, 1, CHAR_LENGTH(@sciezka) - 3))
WHERE nazwa = 'firmy' AND @sciezka IS NOT NULL;

VALUES ('v23-b0r5-scalenie-frachtowce', 'B0R5: jedna firma, baza i platforma na Zephyrii, trzy frachtowce dla agentów')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/024_ladowanie_okretow_tracyn.sql
-- =====================================================================

-- Lądowanie i start małych jednostek z SQL oraz myśliwiec-transportowiec Kom'rk „Tracyn” Venki Tary.
--
-- mapa_obiekty.ladowisko_id: jednostka stoi na lądowisku (lokalizacje.id); NULL = w przestrzeni.
-- mapa_obiekty.start_utc: chwila startu (wznoszenie przez atmosferę na pulpicie załogi).
-- mapa_naped_jednostki.moze_ladowac: tylko małe jednostki lądują (ISD nigdy — chyba że się rozbije).
-- Znacznik 'komrk': sylwetka Kom'rka na mapie (obrócona według kursu).
--
-- Tracyn: własna jednoosobowa flota z dowódcą Tara (Venka Tara), stoi w porcie kosmicznym Nar Shaddaa,
-- Venka na pokładzie (kokpit). Wymaga migracji 023 i paczki Nar Shaddaa (lokacja portu).
-- Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN ladowisko_id BIGINT UNSIGNED NULL AFTER planeta_id,
  ADD COLUMN start_utc DATETIME NULL AFTER przylot_utc,
  MODIFY znacznik ENUM('kolo','trojkat','kwadrat','romb','komrk') NOT NULL DEFAULT 'kolo';

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN moze_ladowac TINYINT(1) NOT NULL DEFAULT 0 AFTER kadlub;

-- Małe jednostki istniejących flot mogą lądować (Gozanti).
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
  SET n.moze_ladowac = 1 WHERE o.klasa LIKE '%Gozanti%' OR o.nazwa LIKE 'Gozanti%';

-- ---------- Tracyn ----------
SET @nar := (SELECT id FROM mapa_planety WHERE nazwa = 'Nar Shaddaa' LIMIT 1);
SET @port := (SELECT id FROM lokalizacje WHERE planeta_id = @nar AND nazwa = 'Port kosmiczny Nar Shaddaa' LIMIT 1);

                          kurs_deg, podejscie, kolor, znacznik, opis, aktywny)
SELECT 'tracyn', 'statek', 'Tracyn', 'myśliwiec-transportowiec', 'Kom''rk', 'Venka Tara', 'Syndykat', 'na lądowisku',
       @nar, @port, p.x, p.y, 90, 'bliska', '#4de2c9', 'komrk', 'Myśliwiec-transportowiec klasy Kom''rk.', 1
FROM mapa_planety p WHERE p.id = @nar
  AND NOT EXISTS (SELECT 1 FROM mapa_obiekty WHERE kod = 'tracyn');

SET @tracyn := (SELECT id FROM mapa_obiekty WHERE kod = 'tracyn' LIMIT 1);

  paliwo, paliwo_maks, paliwo_na_parsek, sprawnosc_reaktora, sprawnosc_hipernapedu, szum_bazowy,
  obrot_deg_na_min, komputer_klasa, komputer_stan, oslony, kadlub, moze_ladowac)
SELECT @tracyn, 100, 60, 1.00, 1000, 5000, 5000, 0.4000, 100, 100, 0.05, 120, 4, 'sprawny', 100, 100, 1
FROM DUAL WHERE @tracyn IS NOT NULL;

SELECT 'tracyn', 'Tracyn', 'Tara', 'aktywna', 'Jednostka Venki Tary.' FROM DUAL
WHERE @tracyn IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mapa_floty WHERE kod = 'tracyn');

SET @flota := (SELECT id FROM mapa_floty WHERE kod = 'tracyn' LIMIT 1);
SELECT @flota, @tracyn, 'flagowy', 1 FROM DUAL WHERE @flota IS NOT NULL AND @tracyn IS NOT NULL;

SELECT @tracyn, 'Tara' FROM DUAL WHERE @tracyn IS NOT NULL;

-- Venka Tara na pokładzie Tracyna (karta postaci: lokacja okret:<id>; znacznik postaci na mapie: na pokładzie).
UPDATE datapad_dane SET payload = JSON_SET(payload,
    '$."482d5fe5bef7".pozycja.lokacja', CONCAT('okret:', @tracyn),
    '$."482d5fe5bef7".pozycja.zmieniono', CAST(UNIX_TIMESTAMP() * 1000 AS UNSIGNED))
WHERE nazwa = 'karty' AND @tracyn IS NOT NULL AND JSON_CONTAINS_PATH(payload, 'one', '$."482d5fe5bef7".pozycja');
UPDATE mapa_obiekty SET na_pokladzie_id = @tracyn, planeta_id = @nar
WHERE legacy_uid = '482d5fe5bef7' AND typ = 'postac' AND @tracyn IS NOT NULL;

VALUES ('v24-ladowanie-tracyn', 'Lądowanie i start małych jednostek, Kom''rk „Tracyn” Venki Tary na Nar Shaddaa')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/025_lokalizator_punkt_skoku.sql
-- =====================================================================

-- Prywatne statki z lokalizatorem oraz lot do punktu skoku (wyjście ze studni grawitacyjnej).
--
-- mapa_obiekty.wlasciciel_login: konto właściciela prywatnego statku (Nawigacja: „Twoje statki”).
-- lokalizator_zasieg_pc / lokalizator_aktywny: lokalizator statku (zasięg od pozycji właściciela);
--   MG wyłącza go np. gdy złodziej go znalazł. ostatnia_pozycja(_utc): ostatni odczyt lokalizatora.
-- mapa_naped_jednostki.predkosc_podswietlna_kms: prędkość podświetlna w drodze do punktu skoku
--   (łuk orbity ok. 1/15 tej prędkości). mapa_rozkazy_skokow.punkt_od_utc: początek lotu do punktu skoku.
--
-- Wymaga migracji 024. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN wlasciciel_login VARCHAR(64) NULL AFTER wlasciciel,
  ADD COLUMN lokalizator_zasieg_pc DECIMAL(10,1) NULL AFTER wlasciciel_login,
  ADD COLUMN lokalizator_aktywny TINYINT(1) NOT NULL DEFAULT 1 AFTER lokalizator_zasieg_pc,
  ADD COLUMN ostatnia_pozycja VARCHAR(255) NULL AFTER lokalizator_aktywny,
  ADD COLUMN ostatnia_pozycja_utc DATETIME NULL AFTER ostatnia_pozycja,
  ADD KEY ix_mapa_obiekty_wlasciciel (wlasciciel_login);

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN predkosc_podswietlna_kms DECIMAL(8,1) NOT NULL DEFAULT 300 AFTER moze_ladowac;

ALTER TABLE mapa_rozkazy_skokow
  ADD COLUMN punkt_od_utc DATETIME NULL AFTER wejscie_utc;

-- Prędkości podświetlne według klasy (km/s).
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.predkosc_podswietlna_kms = 200
  WHERE o.klasa LIKE '%Imperial%' OR o.klasa LIKE '%ISD%' OR o.nazwa LIKE 'ISD%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.predkosc_podswietlna_kms = 350
  WHERE o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.predkosc_podswietlna_kms = 600
  WHERE o.klasa LIKE '%Kom%rk%';

-- Tracyn: prywatny statek Venki Tary (konto Tara), lokalizator o zasięgu 500 pc.
UPDATE mapa_obiekty SET wlasciciel_login = 'Tara', lokalizator_zasieg_pc = 500, lokalizator_aktywny = 1
  WHERE kod = 'tracyn';

VALUES ('v25-lokalizator-punkt-skoku', 'Prywatne statki z lokalizatorem, prędkość podświetlna i lot do punktu skoku')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/026_nar_shaddaa_ksiezyc_tracyn.sql
-- =====================================================================

-- Nar Shaddaa jako księżyc Nal Hutty, typ „pionowe miasto” i (ponownie) Tracyn Venki Tary.
--
-- Mapa miała jeden wpis „Nal Hutta & Nar Shaddaa” (id 1507). Rozdzielamy go: 1507 → „Nal Hutta”
-- (planeta, bagienna), nowy wpis „Nar Shaddaa” (księżyc-miasto) w tym samym układzie. Wszystkie
-- lokacje i postacie przypisane do 1507 (port, hotel, kantyna… z paczki Nar Shaddaa) przechodzą
-- na Nar Shaddaa. planety_cykle.macierz_planeta_id: księżyc krąży wokół planety macierzystej
-- (słońce i rok z jej orbity; na niebie księżyca widać planetę macierzystą).
-- Migracja 024 nie dodała Tracyna (szukała planety „Nar Shaddaa”, której nie było) — robimy to tutaj,
-- razem z właścicielem i lokalizatorem z migracji 025.
--
-- Wymaga migracji 025. Import w phpMyAdmin: zakładka SQL albo Import. Importuj raz.

SET NAMES utf8mb4;

ALTER TABLE planety_cykle
  ADD COLUMN macierz_planeta_id INT UNSIGNED NULL AFTER planeta_id,
  ADD COLUMN promien_wokol_km DECIMAL(14,1) NULL AFTER macierz_planeta_id,
  ADD COLUMN okres_wokol_dni DECIMAL(12,4) NULL AFTER promien_wokol_km,
  ADD COLUMN faza_wokol_deg DECIMAL(7,3) NULL AFTER okres_wokol_dni;

ALTER TABLE planety_gry
  MODIFY typ_planety ENUM('pustynna','lodowa','oceaniczna','lesna','wulkaniczna','gazowa','miasto','bagienna','skalista','pionowe_miasto') NULL;

-- ---------- rozdzielenie Nal Hutty i Nar Shaddaa ----------
SET @nh := (SELECT id FROM mapa_planety WHERE nazwa IN ('Nal Hutta & Nar Shaddaa', 'Nal Hutta') ORDER BY nazwa = 'Nal Hutta' DESC LIMIT 1);
UPDATE mapa_planety SET nazwa = 'Nal Hutta', doba = 87, rok = 413, ksiezyce = GREATEST(ksiezyce, 1),
  srednica = IF(srednica > 0, srednica, 12150), grawitacja = IF(grawitacja > 0, grawitacja, 1.0), slonca = GREATEST(slonca, 1)
  WHERE id = @nh;

SET @nowy := (SELECT MAX(id) + 1 FROM mapa_planety);
SELECT @nowy, 'Nar Shaddaa', region, x + 0.4, y - 0.3, 0.9, slonca, 0, 87, 413, 4400 FROM mapa_planety
WHERE id = @nh AND NOT EXISTS (SELECT 1 FROM (SELECT id FROM mapa_planety WHERE nazwa = 'Nar Shaddaa') t);
SET @ns := (SELECT id FROM mapa_planety WHERE nazwa = 'Nar Shaddaa' LIMIT 1);

VALUES (@ns, 'pionowe_miasto', 'wysoka', 'Kontrola portu Nar Shaddaa', 0, 'Księżyc-miasto Nal Hutty, Przemytniczy Księżyc.')
ON DUPLICATE KEY UPDATE typ_planety = 'pionowe_miasto', urbanizacja = 'wysoka';
VALUES (@nh, 'bagienna', 'niska', 0, 'Planeta Huttów.')
ON DUPLICATE KEY UPDATE typ_planety = 'bagienna';

-- lokacje i postacie z dawnego wspólnego wpisu są na księżycu
UPDATE lokalizacje SET planeta_id = @ns WHERE planeta_id = @nh AND @ns IS NOT NULL;
UPDATE mapa_obiekty SET planeta_id = @ns WHERE planeta_id = @nh AND typ = 'postac' AND @ns IS NOT NULL;

-- cykle: Nal Hutta (doba 87 h, rok 413 dni) i księżyc Nar Shaddaa na jej orbicie
ON DUPLICATE KEY UPDATE doba_h = 87, rok_dni = 413;
VALUES (@ns, @nh, 520000, 20.4, 40, 87, 4400)
ON DUPLICATE KEY UPDATE macierz_planeta_id = @nh, promien_wokol_km = 520000, okres_wokol_dni = 20.4, faza_wokol_deg = 40;
VALUES (@nh, 'Nar Shaddaa', 520000, 20.4, 40, 4400)
ON DUPLICATE KEY UPDATE promien_orbity_km = 520000, okres_dni = 20.4, faza_deg = 40, srednica_km = 4400;

-- ---------- Tracyn (prywatny Kom'rk Venki Tary) ----------
SET @port := (SELECT id FROM lokalizacje WHERE planeta_id = @ns AND nazwa = 'Port kosmiczny Nar Shaddaa' LIMIT 1);
                          frakcja, status, planeta_id, ladowisko_id, x, y, kurs_deg, podejscie, kolor, znacznik, opis, aktywny)
SELECT 'tracyn', 'statek', 'Tracyn', 'myśliwiec-transportowiec', 'Kom''rk', 'Venka Tara', 'Tara', 500, 1,
       'Syndykat', 'na lądowisku', @ns, @port, p.x, p.y, 90, 'bliska', '#4de2c9', 'komrk', 'Myśliwiec-transportowiec klasy Kom''rk.', 1
FROM mapa_planety p WHERE p.id = @ns AND NOT EXISTS (SELECT 1 FROM (SELECT id FROM mapa_obiekty WHERE kod = 'tracyn') t);
UPDATE mapa_obiekty SET wlasciciel_login = 'Tara', lokalizator_zasieg_pc = 500, planeta_id = @ns,
  ladowisko_id = COALESCE(ladowisko_id, @port) WHERE kod = 'tracyn';
SET @tracyn := (SELECT id FROM mapa_obiekty WHERE kod = 'tracyn' LIMIT 1);

  paliwo, paliwo_maks, paliwo_na_parsek, sprawnosc_reaktora, sprawnosc_hipernapedu, szum_bazowy,
  obrot_deg_na_min, komputer_klasa, komputer_stan, oslony, kadlub, moze_ladowac, predkosc_podswietlna_kms)
SELECT @tracyn, 100, 60, 1.00, 1000, 5000, 5000, 0.4000, 100, 100, 0.05, 120, 4, 'sprawny', 100, 100, 1, 600
FROM DUAL WHERE @tracyn IS NOT NULL;

SELECT 'tracyn', 'Tracyn', 'Tara', 'aktywna', 'Prywatny statek Venki Tary.' FROM DUAL
WHERE @tracyn IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mapa_floty WHERE kod = 'tracyn');
SET @flota := (SELECT id FROM mapa_floty WHERE kod = 'tracyn' LIMIT 1);
SELECT @flota, @tracyn, 'flagowy', 1 FROM DUAL WHERE @flota IS NOT NULL AND @tracyn IS NOT NULL;

VALUES ('v26-nar-shaddaa-ksiezyc-tracyn', 'Nar Shaddaa jako księżyc Nal Hutty (pionowe miasto) i Tracyn Venki Tary')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/027_nar_shaddaa_wspolny_uklad.sql
-- =====================================================================

-- Nar Shaddaa w układzie Nal Hutty: te same współrzędne mapy (jedno słońce, jeden układ).
-- Księżyc rysowany jest na orbicie Nal Hutty, a nie jako osobny układ. Przy równej odległości
-- kod wybiera planetę (niższe id), więc okręty przylatujące na współrzędne układu trafiają do Nal Hutty.
--
-- Wymaga migracji 026. Import w phpMyAdmin: zakładka SQL albo Import. Ponowny import niczego nie psuje.

SET NAMES utf8mb4;

SET @nh := (SELECT id FROM mapa_planety WHERE nazwa = 'Nal Hutta' LIMIT 1);
SET @ns := (SELECT id FROM mapa_planety WHERE nazwa = 'Nar Shaddaa' LIMIT 1);
SET @x := (SELECT x FROM mapa_planety WHERE id = @nh);
SET @y := (SELECT y FROM mapa_planety WHERE id = @nh);

UPDATE mapa_planety SET x = @x, y = @y WHERE id = @ns AND @x IS NOT NULL;
UPDATE mapa_obiekty SET x = @x, y = @y WHERE planeta_id = @ns AND @x IS NOT NULL;

VALUES ('v27-nar-shaddaa-wspolny-uklad', 'Nar Shaddaa we współrzędnych układu Nal Hutty (bez osobnego słońca)')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/028_lot_podswietlny_poklad.sql
-- =====================================================================

-- Lot podświetlny i role osób na pokładzie.
--
-- mapa_obiekty.lot_*: trwający lot podświetlny jednostki (czas gry 1:1, MG może go przyspieszyć).
--   lot_start_x/y → lot_cel_x/y (współrzędne mapy, pc), lot_cel_planeta_id (planeta albo księżyc
--   celu w tym samym układzie), lot_km (długość trasy), lot_od_utc (start silników po obrocie)
--   i lot_do_utc (przylot). Po przylocie kolumny wracają do NULL.
-- mapa_obiekty.rola_na_pokladzie: postać na pokładzie statku jest pasażerem albo więźniem
--   (karta statku na mapie: zakładki „Pasażerowie” i „Więźniowie”; MG zmienia rolę).
-- mapa_naped_jednostki.predkosc_podswietlna_kms: nowe prędkości przelotowe (km/s); ta sama prędkość
--   liczy też drogę do punktu skoku, więc ten etap się skraca.
--
-- Import w phpMyAdmin: zakładka SQL albo Import. Ponowny import niczego nie psuje
-- (jeśli kolumny już są, ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku od UPDATE).

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN lot_start_x DECIMAL(12,1) NULL,
  ADD COLUMN lot_start_y DECIMAL(12,1) NULL,
  ADD COLUMN lot_cel_x DECIMAL(12,1) NULL,
  ADD COLUMN lot_cel_y DECIMAL(12,1) NULL,
  ADD COLUMN lot_cel_planeta_id INT UNSIGNED NULL,
  ADD COLUMN lot_km DECIMAL(20,1) NULL,
  ADD COLUMN lot_od_utc DATETIME NULL,
  ADD COLUMN lot_do_utc DATETIME NULL,
  ADD COLUMN rola_na_pokladzie ENUM('pasazer','wiezien') NOT NULL DEFAULT 'pasazer';

-- Prędkości podświetlne według klasy (km/s).
UPDATE mapa_naped_jednostki SET predkosc_podswietlna_kms = 1500;
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.predkosc_podswietlna_kms = 2000
  WHERE o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%' OR o.klasa LIKE '%Gozanti%' OR o.nazwa LIKE 'Gozanti%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.predkosc_podswietlna_kms = 3000
  WHERE o.klasa LIKE '%Kom%rk%';

VALUES ('v28-lot-podswietlny-poklad', 'Lot podświetlny (mapa_obiekty.lot_*), rola na pokładzie, prędkości podświetlne')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/029_lokacje_tatooine.sql
-- =====================================================================

-- Lokacje Tatooine (3 BBY): regiony, miasta i osady, infrastruktura miast, stanowiska portu Mos Eisley.
-- Układ współrzędnych gry: +X wschód, +Y północ (km), (0,0) — środek zamieszkałego obszaru.
-- Planeta wyszukiwana po nazwie. Nie zmienia struktury tabel ani istniejących rekordów.
-- Import w phpMyAdmin: zakładka SQL albo Import; ponowny import niczego nie psuje.

SET NAMES utf8mb4;

SET @pl := (SELECT id FROM mapa_planety WHERE nazwa = 'Tatooine' LIMIT 1);

DROP TEMPORARY TABLE IF EXISTS tmp_import_lokacji;
CREATE TEMPORARY TABLE tmp_import_lokacji (
  poziom TINYINT UNSIGNED NOT NULL,
  nazwa VARCHAR(200) NOT NULL PRIMARY KEY,
  rodzic_nazwa VARCHAR(200) NULL,
  rodzic_id BIGINT UNSIGNED NULL,
  typ ENUM('uklad','orbita','powierzchnia','lokacja','budynek','ladowisko') NOT NULL,
  rodzaj ENUM('hangar','port','hotel','bankomat','sklep','kantyna','biuro','garaz','baza','magazyn','platforma','inne') NULL,
  x_km DECIMAL(12,3) NOT NULL,
  y_km DECIMAL(12,3) NOT NULL,
  publiczna TINYINT(1) NOT NULL,
  status ENUM('aktywna','zamknieta','zniszczona') NOT NULL,
  opis TEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Import poziom po poziomie: rodzic odnajdywany po nazwie na tej planecie. Istniejące rekordy
-- (ta sama planeta i nazwa) zostają bez zmian, więc ponowny import tylko dokłada brakujące.
START TRANSACTION;

UPDATE tmp_import_lokacji t JOIN lokalizacje r ON r.planeta_id = @pl AND r.nazwa = t.rodzic_nazwa
SET t.rodzic_id = r.id WHERE t.poziom = 1;
SELECT typ, rodzaj, rodzic_id, NULL, @pl, nazwa, x_km, y_km, publiczna, status, opis FROM tmp_import_lokacji
WHERE poziom = 1 AND @pl IS NOT NULL AND (rodzic_nazwa IS NULL OR rodzic_id IS NOT NULL)
ON DUPLICATE KEY UPDATE id = id;

UPDATE tmp_import_lokacji t JOIN lokalizacje r ON r.planeta_id = @pl AND r.nazwa = t.rodzic_nazwa
SET t.rodzic_id = r.id WHERE t.poziom = 2;
SELECT typ, rodzaj, rodzic_id, NULL, @pl, nazwa, x_km, y_km, publiczna, status, opis FROM tmp_import_lokacji
WHERE poziom = 2 AND @pl IS NOT NULL AND (rodzic_nazwa IS NULL OR rodzic_id IS NOT NULL)
ON DUPLICATE KEY UPDATE id = id;

UPDATE tmp_import_lokacji t JOIN lokalizacje r ON r.planeta_id = @pl AND r.nazwa = t.rodzic_nazwa
SET t.rodzic_id = r.id WHERE t.poziom = 3;
SELECT typ, rodzaj, rodzic_id, NULL, @pl, nazwa, x_km, y_km, publiczna, status, opis FROM tmp_import_lokacji
WHERE poziom = 3 AND @pl IS NOT NULL AND (rodzic_nazwa IS NULL OR rodzic_id IS NOT NULL)
ON DUPLICATE KEY UPDATE id = id;

UPDATE tmp_import_lokacji t JOIN lokalizacje r ON r.planeta_id = @pl AND r.nazwa = t.rodzic_nazwa
SET t.rodzic_id = r.id WHERE t.poziom = 4;
SELECT typ, rodzaj, rodzic_id, NULL, @pl, nazwa, x_km, y_km, publiczna, status, opis FROM tmp_import_lokacji
WHERE poziom = 4 AND @pl IS NOT NULL AND (rodzic_nazwa IS NULL OR rodzic_id IS NOT NULL)
ON DUPLICATE KEY UPDATE id = id;

COMMIT;

-- Kontrola: lokacje z paczki w bazie, brakujące (np. brak planety albo rodzica) i osierocone.
SELECT COUNT(*) AS w_paczce,
  SUM(l.id IS NOT NULL) AS w_bazie,
  SUM(l.id IS NULL) AS brakujace,
  SUM(t.rodzic_nazwa IS NOT NULL AND l.id IS NOT NULL AND l.rodzic_id IS NULL) AS bez_rodzica
FROM tmp_import_lokacji t LEFT JOIN lokalizacje l ON l.planeta_id = @pl AND l.nazwa = t.nazwa;

DROP TEMPORARY TABLE IF EXISTS tmp_import_lokacji;

VALUES ('v29-lokacje-tatooine', 'Lokacje: Tatooine (56)')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

