-- =====================================================================
-- migracje/033_dlugosc_okretow_jakosc_podzespolow.sql
-- =====================================================================

-- Rzeczywista skala na mapie i skutki przerwania skoku.
--
-- mapa_obiekty.dlugosc_m: długość jednostki (m) — mapa w rzeczywistej skali rysuje sylwetkę tej długości.
-- mapa_naped_jednostki.jakosc_podzespolow (1–5, domyślnie 3): jakość reaktora, hipernapędu i osłon.
--   Przerwanie skoku w nadprzestrzeni uszkadza je tym mniej, im wyższa jakość (1: ×1,6 … 5: ×0,4).
--
-- Import w phpMyAdmin: zakładka SQL albo Import. Ponowny import: ALTER zgłosi „Duplicate column” —
-- wtedy wystarczy reszta pliku od UPDATE.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN dlugosc_m DECIMAL(8,1) NULL;

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN jakosc_podzespolow TINYINT UNSIGNED NOT NULL DEFAULT 3;

-- Długości według klasy (m); pozostałe jednostki 100 m.
UPDATE mapa_obiekty SET dlugosc_m = 1600
  WHERE dlugosc_m IS NULL AND (klasa LIKE '%Imperial%' OR klasa LIKE '%ISD%' OR nazwa LIKE 'ISD%');
UPDATE mapa_obiekty SET dlugosc_m = 450
  WHERE dlugosc_m IS NULL AND (klasa LIKE '%Arquitens%' OR nazwa LIKE 'Arquitens%');
UPDATE mapa_obiekty SET dlugosc_m = 64
  WHERE dlugosc_m IS NULL AND (klasa LIKE '%Gozanti%' OR nazwa LIKE 'Gozanti%');
UPDATE mapa_obiekty SET dlugosc_m = 75
  WHERE dlugosc_m IS NULL AND klasa LIKE '%Kom%rk%';
UPDATE mapa_obiekty SET dlugosc_m = 100
  WHERE dlugosc_m IS NULL AND typ IN ('statek', 'jednostka', 'pojazd');

VALUES ('v33-dlugosc-okretow-jakosc', 'Długość jednostek (mapa w rzeczywistej skali), jakość podzespołów (przerwanie skoku)')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/034_lokacje_corellia.sql
-- =====================================================================


-- ============================================================
-- HOLOLINK
-- CORELLIA
-- Okres: 3 BBY
-- Import hierarchicznych lokacji powierzchniowych
--
-- Planeta: mapa_planety.nazwa = 'Corellia' (ID pobierane z bazy)
-- Tabela docelowa: lokalizacje
--
-- Paczka danych bez zmian struktury. Powtórny import nie tworzy duplikatów.
-- W razie błędu przed COMMIT przerwij import i wykonaj ROLLBACK w tej samej sesji.
--
-- Zasady:
-- 1. Nie modyfikujemy struktury istniejącej bazy.
-- 2. Nie nadajemy ręcznie ID.
-- 3. Nie usuwamy istniejących rekordów.
-- 4. Ponowne wykonanie nie tworzy duplikatów.
-- 5. Hierarchia jest odtwarzana przez rodzic_id.
-- 6. układ_id pozostaje NULL.
-- 7. Współrzędne NULL oznaczają brak wiarygodnej
--    georeferencji, a nie brak lokalizacji.
--
-- Oznaczenia źródeł w opisach:
-- [CANON]     - kanon Star Wars
-- [LEGENDS]   - materiały Star Wars Legends
-- [INFERRED]  - lokalizacja lub podział rekonstruowany
-- [CUSTOM]    - element porządkowy HOLOLINK
-- [MIXED]     - nazwa lub obiekt oparty na źródłach
--              z uzupełnieniem struktury na potrzeby gry
-- ============================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------
-- KONTROLA PLANETY
-- ------------------------------------------------------------

SET @corellia_id := (SELECT id FROM mapa_planety WHERE nazwa = 'Corellia' LIMIT 1);

SELECT COUNT(*) INTO @corellia_exists
FROM mapa_planety
WHERE id = @corellia_id;

-- Podgląd kontroli. Gdy Corellii nie ma w bazie, część zapisująca nie doda żadnych rekordów.
SELECT @corellia_id IS NOT NULL AS corellia_znaleziona, @corellia_id AS planeta_id;

-- ------------------------------------------------------------
-- TABELA ROBOCZA
-- ------------------------------------------------------------

DROP TEMPORARY TABLE IF EXISTS tmp_import_corellia_lokacje;

CREATE TEMPORARY TABLE tmp_import_corellia_lokacje (
    klucz VARCHAR(100) NOT NULL,
    rodzic_klucz VARCHAR(100) DEFAULT NULL,
    poziom TINYINT UNSIGNED NOT NULL,
    typ ENUM(
        'uklad',
        'orbita',
        'powierzchnia',
        'lokacja',
        'budynek',
        'ladowisko'
    ) NOT NULL,
    rodzaj ENUM(
        'hangar',
        'port',
        'hotel',
        'bankomat',
        'sklep',
        'kantyna',
        'biuro',
        'garaz',
        'baza',
        'magazyn',
        'platforma',
        'inne'
    ) DEFAULT NULL,
    nazwa VARCHAR(200) NOT NULL,
    x_km DECIMAL(10,6) DEFAULT NULL,
    y_km DECIMAL(10,6) DEFAULT NULL,
    publiczna TINYINT(1) NOT NULL DEFAULT 0,
    status ENUM(
        'aktywna',
        'zamknieta',
        'zniszczona'
    ) NOT NULL DEFAULT 'aktywna',
    opis TEXT,
    PRIMARY KEY (klucz),
    KEY ix_tmp_rodzic (rodzic_klucz),
    KEY ix_tmp_poziom (poziom)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

