-- ------------------------------------------------------------
-- WALIDACJA PO IMPORCIE
-- ------------------------------------------------------------

SELECT
 'Corellia' AS planeta,
 @corellia_id AS planeta_id,
 COUNT(*) AS liczba_lokalizacji
FROM lokalizacje
WHERE planeta_id = @corellia_id;

-- Kontrola rekordów bez rodzica poza korzeniem.
SELECT
 l.id,
 l.nazwa,
 l.typ,
 l.rodzic_id
FROM lokalizacje l
WHERE l.planeta_id = @corellia_id
  AND l.nazwa <> 'Corellia — mapa powierzchni'
  AND l.rodzic_id IS NULL;

-- Kontrola sierot: rodzic musi należeć do tej samej planety.
SELECT
 dziecko.id,
 dziecko.nazwa,
 dziecko.rodzic_id,
 rodzic.planeta_id AS planeta_rodzica
FROM lokalizacje dziecko
LEFT JOIN lokalizacje rodzic
  ON rodzic.id = dziecko.rodzic_id
WHERE dziecko.planeta_id = @corellia_id
  AND dziecko.rodzic_id IS NOT NULL
  AND (
    rodzic.id IS NULL
    OR rodzic.planeta_id <> @corellia_id
  );

-- Kontrola duplikatów nazw na planecie.
SELECT
 planeta_id,
 nazwa,
 COUNT(*) AS liczba
FROM lokalizacje
WHERE planeta_id = @corellia_id
GROUP BY planeta_id, nazwa
HAVING COUNT(*) > 1;

-- Zestawienie hierarchii i typów.
SELECT
 typ,
 rodzaj,
 status,
 publiczna,
 COUNT(*) AS liczba
FROM lokalizacje
WHERE planeta_id = @corellia_id
GROUP BY typ, rodzaj, status, publiczna
ORDER BY typ, rodzaj, status;

-- Lista zaimportowanych lokalizacji.
SELECT
 l.id,
 l.nazwa,
 l.typ,
 l.rodzaj,
 p.nazwa AS rodzic,
 l.x_km,
 l.y_km,
 l.publiczna,
 l.status,
 l.opis
FROM lokalizacje l
LEFT JOIN lokalizacje p
  ON p.id = l.rodzic_id
WHERE l.planeta_id = @corellia_id
ORDER BY l.id;

-- Sprzątanie tabeli roboczej.
DROP TEMPORARY TABLE IF EXISTS tmp_import_corellia_lokacje;

-- KONIEC IMPORTU CORELLII

-- =====================================================================
-- migracje/035_promy_w_hangarach.sql
-- =====================================================================

-- Promy w hangarach okrętów.
--
-- mapa_obiekty.okret_macierzysty_id — okręt, do którego hangaru należy jednostka (prom).
-- mapa_obiekty.w_hangarze (0/1) — jednostka stoi teraz w hangarze okrętu macierzystego: jej pozycja
--   idzie za okrętem, nie ma osobnego znacznika na mapie, nie wykona rozkazu (najpierw wylot).
-- mapa_obiekty.ladowanie_cel_id — lądowisko, na które jednostka sama wyląduje, gdy dotrze na bliską
--   orbitę (prom: „lot na planetę” = wylot + dolot + lądowanie jednym rozkazem).
--
-- Każdy ISD dostaje prom klasy Lambda (np. „Lambda Walako”) w swoim hangarze. Prom jest w osobnej
-- podgrupie floty ISD bez własnego dowódcy, więc dowodzi nim dowódca floty ISD (dziś kpt. Stingert
-- na Walako; kolejni kapitanowie dostają prom razem z okrętem).
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku
-- od INSERT (promy i grupy nie powielą się).

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN okret_macierzysty_id BIGINT UNSIGNED NULL,
  ADD COLUMN w_hangarze TINYINT(1) NOT NULL DEFAULT 0,
  ADD COLUMN ladowanie_cel_id BIGINT UNSIGNED NULL,
  ADD KEY ix_mapa_obiekty_hangar (okret_macierzysty_id, w_hangarze),
  ADD CONSTRAINT fk_mapa_obiekty_macierzysty FOREIGN KEY (okret_macierzysty_id) REFERENCES mapa_obiekty (id) ON DELETE SET NULL;

-- Prom Lambda w hangarze każdego ISD (nazwa: „Lambda ” + nazwa okrętu bez klasy, np. Walako).
                          okret_macierzysty_id, w_hangarze, kurs_deg, orbita_deg, podejscie, dlugosc_m)
SELECT CONCAT('prom-', i.kod),
       'statek',
       CONCAT('Lambda ', TRIM(REPLACE(REPLACE(REPLACE(REPLACE(i.nazwa, 'ISD I ', ''), '„', ''), '”', ''), '"', ''))),
       'prom', 'Lambda T-4a', i.wlasciciel, i.frakcja, 'w hangarze', i.planeta_id, i.x, i.y, i.kolor, 'trojkat',
       CONCAT('Prom klasy Lambda z hangaru ', i.nazwa, '.'), 1,
       i.id, 1, i.kurs_deg, i.orbita_deg, i.podejscie, 20
FROM mapa_obiekty i
WHERE i.typ = 'statek' AND i.aktywny = 1 AND i.okret_macierzysty_id IS NULL
  AND (i.klasa LIKE '%ISD%' OR i.klasa LIKE '%Imperial%')
  AND NOT EXISTS (SELECT 1 FROM mapa_obiekty p WHERE p.kod = CONCAT('prom-', i.kod));

-- Napęd promu: hipernapęd klasy 1, mały zbiornik, zwrotny, może lądować.
  paliwo, paliwo_maks, paliwo_na_parsek, sprawnosc_reaktora, sprawnosc_hipernapedu, szum_bazowy,
  obrot_deg_na_min, komputer_klasa, komputer_stan, oslony, kadlub, moze_ladowac)
SELECT p.id, 100, 60, 1.00, 1000, 4000, 4000, 0.4000, 100, 100, 0.05, 120, 3, 'sprawny', 100, 100, 1
FROM mapa_obiekty p WHERE p.kod LIKE 'prom-%' AND p.okret_macierzysty_id IS NOT NULL;

-- Podgrupa floty ISD na prom (bez dowódcy: dziedziczy dowódcę floty ISD).
SELECT CONCAT('grupa-', p.kod), p.nazwa, j.flota_id, 'aktywna', CONCAT('Prom z hangaru ', i.nazwa, '.')
FROM mapa_obiekty p
JOIN mapa_obiekty i ON i.id = p.okret_macierzysty_id
JOIN mapa_floty_jednostki j ON j.obiekt_id = i.id
WHERE p.kod LIKE 'prom-%'
  AND NOT EXISTS (SELECT 1 FROM mapa_floty f WHERE f.kod = CONCAT('grupa-', p.kod));

SELECT f.id, p.id, 'prom', 1
FROM mapa_obiekty p JOIN mapa_floty f ON f.kod = CONCAT('grupa-', p.kod)
WHERE p.kod LIKE 'prom-%';

-- Kto widzi ISD na mapie, widzi też jego prom (po wylocie).
SELECT p.id, d.konto_login
FROM mapa_obiekty p JOIN mapa_obiekty_dostep d ON d.obiekt_id = p.okret_macierzysty_id
WHERE p.kod LIKE 'prom-%';

VALUES ('v35-promy-w-hangarach', 'Promy Lambda w hangarach ISD: wylot, lot na planetę z lądowaniem, powrót do hangaru')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- Kontrola: promy i ich okręty.
SELECT p.id, p.nazwa, i.nazwa AS okret, p.w_hangarze, f.nazwa AS grupa
FROM mapa_obiekty p JOIN mapa_obiekty i ON i.id = p.okret_macierzysty_id
LEFT JOIN mapa_floty_jednostki j ON j.obiekt_id = p.id LEFT JOIN mapa_floty f ON f.id = j.flota_id
WHERE p.kod LIKE 'prom-%';

-- =====================================================================
-- migracje/036_wnetrza_okretow_okna.sql
-- =====================================================================

-- Wnętrza okrętów: plan pomieszczeń i okna.
--
-- mapa_obiekty.plan_wnetrza_id — korzeń planu wnętrza w `lokalizacje` (szablon klasy okrętu). Wszystkie
--   ISD I korzystają z „Imperial Star Destroyer Type I – wnętrze”; inna klasa dostanie własny szablon.
-- lokalizacje.okno — co widać z pomieszczenia:
--   przod  — okna mostka (wzdłuż kursu),
--   lewa / prawa — boczne iluminatory lewej / prawej burty (prostopadle do kursu; w nadprzestrzeni
--          smugi lecą poziomo od dziobu ku rufie),
--   hangar — kosmos przez wrota hangaru,
--   brak   — pomieszczenie bez okien.
--   Przydział początkowy niżej (pokład mostka: przód; hangary: wrota; kwatery i sale oficerskie,
--   mesy, kantyny: burty na przemian; reszta bez okien). MG może zmienić każde pomieszczenie:
--   UPDATE lokalizacje SET okno = 'lewa' WHERE id = …;
--
-- Pomieszczenie postaci na okręcie zapisuje gra (karta postaci); kapitan zaczyna na Mostku głównym,
-- pozostali w Głównym korytarzu centralnym. Prom wsiada się na Stanowisku obsługi promów Lambda.
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku
-- od SET @plan (przydział okien nadpisze się wartościami z tego pliku).

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN plan_wnetrza_id BIGINT UNSIGNED NULL,
  ADD CONSTRAINT fk_mapa_obiekty_plan_wnetrza FOREIGN KEY (plan_wnetrza_id) REFERENCES lokalizacje (id) ON DELETE SET NULL;

ALTER TABLE lokalizacje
  ADD COLUMN okno ENUM('przod','lewa','prawa','hangar','brak') NULL;

SET @plan := (SELECT id FROM lokalizacje WHERE rodzic_id IS NULL AND nazwa LIKE 'Imperial Star Destroyer Type I%wn_trze' ORDER BY id LIMIT 1);

-- Plan wnętrza dla wszystkich ISD I (nie dla promów z ich hangarów).
UPDATE mapa_obiekty SET plan_wnetrza_id = @plan
WHERE @plan IS NOT NULL AND typ = 'statek' AND okret_macierzysty_id IS NULL
  AND (klasa LIKE '%ISD%' OR klasa LIKE '%Imperial%' OR nazwa LIKE 'ISD%');

-- Drzewo planu (tabela robocza: UPDATE nie może czytać aktualizowanej tabeli w podzapytaniu).
DROP TEMPORARY TABLE IF EXISTS tmp_plan_wnetrza;
CREATE TEMPORARY TABLE tmp_plan_wnetrza (id BIGINT UNSIGNED NOT NULL PRIMARY KEY, mostek TINYINT(1) NOT NULL DEFAULT 0);
WITH RECURSIVE drzewo AS (
  SELECT id, 0 AS mostek FROM lokalizacje WHERE id = @plan
  UNION ALL
  SELECT c.id, IF(d.mostek = 1 OR c.nazwa LIKE '%Pokład 01%', 1, 0) FROM lokalizacje c JOIN drzewo d ON c.rodzic_id = d.id
)
SELECT id, mostek FROM drzewo;

-- Okna: najpierw całe wnętrze bez okien, potem pokład mostka (i wszystko pod nim) — okna przednie.
UPDATE lokalizacje l JOIN tmp_plan_wnetrza t ON t.id = l.id SET l.okno = IF(t.mostek = 1, 'przod', 'brak');

-- Hangary: wrota.
UPDATE lokalizacje SET okno = 'hangar' WHERE okno IS NOT NULL AND rodzaj = 'hangar';

-- Burty: kwatery i sale oficerskie, mesy, kantyny, rekreacja, oddział szpitalny (na przemian lewa / prawa).
UPDATE lokalizacje SET okno = IF(id % 2 = 0, 'lewa', 'prawa')
WHERE okno = 'brak' AND (
     nazwa LIKE '%Kwatera kapitana' OR nazwa LIKE '%Gabinet dowódcy' OR nazwa LIKE '%Kwatera adiutanta dowódcy'
  OR nazwa LIKE '%Kwatery oficerów sztabowych' OR nazwa LIKE '%Sala odpraw dowództwa' OR nazwa LIKE '%Sala narad sztabu'
  OR nazwa LIKE '%Sala konferencyjna' OR nazwa LIKE '%Salon oficerski' OR nazwa LIKE '%Mesa oficerska'
  OR nazwa LIKE '%Kwatery starszych oficerów' OR nazwa LIKE '%Kantyna główna' OR nazwa LIKE '%Kantyna pomocnicza'
  OR nazwa LIKE '%Sala rekreacyjna' OR nazwa LIKE '%Pomieszczenie wypoczynkowe załogi' OR nazwa LIKE '%Oddział szpitalny');

DROP TEMPORARY TABLE IF EXISTS tmp_plan_wnetrza;

VALUES ('v36-wnetrza-okretow', 'Plan wnętrza okrętów (szablon ISD I), pomieszczenia postaci, okna przednie, boczne, hangar, brak')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- Kontrola: okręty z planem i okna w planie.
SELECT id, nazwa, klasa, plan_wnetrza_id FROM mapa_obiekty WHERE plan_wnetrza_id IS NOT NULL;
SELECT okno, COUNT(*) AS pomieszczenia FROM lokalizacje WHERE okno IS NOT NULL GROUP BY okno;
SELECT id, nazwa, okno FROM lokalizacje WHERE okno IN ('przod', 'lewa', 'prawa', 'hangar') ORDER BY okno, nazwa;

-- =====================================================================
-- migracje/037_pozycje_w_ukladzie.sql
-- =====================================================================

-- Pozycje wewnątrz układu planetarnego.
--
-- Dotąd jednostka w układzie mogła być tylko przy planecie. Teraz może stać w dowolnym punkcie układu:
-- mapa_obiekty.uklad_kx / uklad_ky — przesunięcie od słońca układu w km (osie mapy: x na wschód,
-- y na północ), gdy jednostka nie stoi przy planecie (planeta_id NULL). x, y to dalej współrzędne układu.
--   • skok na „krawędź układu” kończy się na brzegu całego układu (50 · √L j.a. od słońca),
--   • skok i lot podświetlny do punktu między planetą a słońcem,
--   • studnie grawitacyjne są wokół ciał (słońce: 20 jego promieni, planeta: 100 jej promieni), nie wokół
--     całego układu; skok automatem na orbitę planety dalej jest dozwolony.
-- Lot podświetlny i skok pamiętają początek i cel w km (lot_*_kx/ky, wyjscie_kx/ky).
--
-- Dawne pozycje „krawędź układu” (orbita 60 promieni planety) stają się daleką orbitą; na prawdziwy
-- brzeg układu prowadzi teraz skok z wariantem „krawędź układu” albo lot podświetlny.
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN uklad_kx DECIMAL(20,1) NULL,
  ADD COLUMN uklad_ky DECIMAL(20,1) NULL,
  ADD COLUMN lot_start_kx DECIMAL(20,1) NULL,
  ADD COLUMN lot_start_ky DECIMAL(20,1) NULL,
  ADD COLUMN lot_cel_kx DECIMAL(20,1) NULL,
  ADD COLUMN lot_cel_ky DECIMAL(20,1) NULL;

ALTER TABLE mapa_rozkazy_skokow_jednostki
  ADD COLUMN wyjscie_kx DECIMAL(20,1) NULL,
  ADD COLUMN wyjscie_ky DECIMAL(20,1) NULL;

-- Dawna krawędź (60 promieni planety) to teraz daleka orbita; na brzeg układu prowadzi lot podświetlny.
UPDATE mapa_obiekty SET podejscie = 'daleka' WHERE podejscie = 'krawedz';

VALUES ('v37-pozycje-w-ukladzie', 'Pozycje w układzie (km od słońca), krawędź całego układu, studnie wokół ciał')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/038_przyspieszenie_podswietlne.sql
-- =====================================================================

-- ZASTĄPIONA przez 039 (prędkość przelotowa w pc na dobę): tej migracji nie trzeba importować;
-- jeśli już jest w bazie, kolumna przyspieszenie_g po prostu nie jest używana.
--
-- Silniki podświetlne: przyspieszenie zamiast stałej prędkości.
--
-- mapa_naped_jednostki.przyspieszenie_g — przyspieszenie (w G = 9,81 m/s²). Lot podświetlny to rozpędzanie
-- do połowy drogi i hamowanie: czas = 2 · √(droga / przyspieszenie). Flota leci tempem najsłabszej jednostki.
-- ISD (2300 G): planeta → księżyc ok. 5 min, 1 j.a. ok. 1,4 h, brzeg układu (50 j.a.) → planeta ok. 10 h,
-- 1 pc ok. 27 dni. MG może zmienić każdą jednostkę: UPDATE mapa_naped_jednostki SET przyspieszenie_g = …
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN przyspieszenie_g DECIMAL(8,1) NOT NULL DEFAULT 2500;

UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
SET n.przyspieszenie_g = CASE
  WHEN o.klasa LIKE '%Lambda%' THEN 1400
  WHEN o.klasa LIKE '%ISD%' OR o.klasa LIKE '%Imperial%' OR o.nazwa LIKE 'ISD%' THEN 2300
  WHEN o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%' THEN 3000
  WHEN o.klasa LIKE '%Gozanti%' OR o.nazwa LIKE 'Gozanti%' THEN 2500
  WHEN o.klasa LIKE '%Kom%rk%' THEN 3500
  ELSE 2500 END;

VALUES ('v38-przyspieszenie-podswietlne', 'Lot podświetlny z przyspieszeniem (G): rozpędzanie i hamowanie')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

SELECT o.nazwa, o.klasa, n.przyspieszenie_g FROM mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id ORDER BY n.przyspieszenie_g, o.nazwa;

-- =====================================================================
-- migracje/039_predkosc_podswietlna_pc_doba.sql
-- =====================================================================

-- Silniki podświetlne: szybki rozpęd i hamowanie, potem stała prędkość przelotowa (pc na dobę).
--
-- mapa_naped_jednostki.podswietlna_pc_doba — prędkość przelotowa. Czas lotu = 2 min (rozpęd i hamowanie)
-- + droga / prędkość. Skala: Sokół Millennium (najlepsze silniki) leci z Hoth na Bespin (132,9 pc na mapie)
-- w ok. 3 dni = 45 pc/doba. Loty w obrębie układu trwają ok. 2 minut (sam przelot to ułamek sekundy).
-- Zastępuje przyspieszenie z migracji 038 (kolumna przyspieszenie_g, jeśli jest, nie jest już używana).
-- MG może zmienić każdą jednostkę (profil napędu w panelu albo UPDATE … SET podswietlna_pc_doba = …).
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN podswietlna_pc_doba DECIMAL(8,2) NOT NULL DEFAULT 20;

UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id
SET n.podswietlna_pc_doba = CASE
  WHEN o.klasa LIKE '%YT-1300%' OR o.nazwa LIKE '%Sok_ł%' OR o.nazwa LIKE '%Millennium%' THEN 45
  WHEN o.klasa LIKE '%Kom%rk%' THEN 35
  WHEN o.klasa LIKE '%Arquitens%' OR o.nazwa LIKE 'Arquitens%' THEN 28
  WHEN o.klasa LIKE '%Lambda%' THEN 15
  WHEN o.klasa LIKE '%ISD%' OR o.klasa LIKE '%Imperial%' OR o.nazwa LIKE 'ISD%' THEN 22
  WHEN o.klasa LIKE '%Gozanti%' OR o.nazwa LIKE 'Gozanti%' THEN 20
  ELSE 20 END;

VALUES ('v39-predkosc-podswietlna-pc-doba', 'Lot podświetlny: szybki rozpęd, stała prędkość przelotowa w pc na dobę (Sokół 45)')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

SELECT o.nazwa, o.klasa, n.podswietlna_pc_doba FROM mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id ORDER BY n.podswietlna_pc_doba DESC, o.nazwa;

-- =====================================================================
-- migracje/040_karta_eote.sql
-- =====================================================================

-- Karta postaci NPC w systemie Star Wars: Edge of the Empire (CV): cechy, umiejętności, talenty, sprzęt, historia.
--
-- Jedna karta na osobę (osoby.podmiot_id) jako JSON — ten sam format co karta gracza (klucz „eote” w karcie postaci).
-- Zapisuje ją generator postaci w panelu MG (zakładka „Generator postaci”). Karty graczy nie potrzebują tej tabeli.
--
-- Import w phpMyAdmin. Ponowny import jest bezpieczny (CREATE TABLE IF NOT EXISTS).

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS osoby_karta_eote (
  osoba_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  dane MEDIUMTEXT NOT NULL,
  zmieniono TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (osoba_id) REFERENCES osoby (podmiot_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- migracje/041_karty_eote_sql.sql
-- =====================================================================

-- CV Edge of the Empire w SQL dla postaci graczy i NPC.
-- Każde pole karty jest osobnym wierszem; nie przechowujemy blobu JSON.
-- Stare CV graczy z datapad_dane i NPC z osoby_karta_eote są przenoszone
-- automatycznie przy pierwszym odczycie po wdrożeniu nowego API.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS eote_cv_karty (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  legacy_uid VARCHAR(64) NULL,
  osoba_id BIGINT UNSIGNED NULL,
  zmieniono TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_eote_cv_uid (legacy_uid),
  UNIQUE KEY uq_eote_cv_osoba (osoba_id),
  CHECK ((legacy_uid IS NOT NULL AND osoba_id IS NULL) OR (legacy_uid IS NULL AND osoba_id IS NOT NULL)),
  FOREIGN KEY (osoba_id) REFERENCES osoby (podmiot_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS eote_cv_wartosci (
  karta_id BIGINT UNSIGNED NOT NULL,
  sciezka VARCHAR(512) NOT NULL,
  typ ENUM('obiekt','lista','tekst','liczba','logiczna','null') NOT NULL,
  wartosc MEDIUMTEXT NULL,
  PRIMARY KEY (karta_id, sciezka),
  FOREIGN KEY (karta_id) REFERENCES eote_cv_karty (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- migracje/041_stocznia_naprawy.sql
-- =====================================================================

-- Stocznia naprawcza (Kuat): kolejka napraw podzespołów okrętów.
--
-- Gracz (kapitan / dowódca floty) przy Kuat jednym kliknięciem oddaje okręt do naprawy: każdy uszkodzony podzespół
-- (reaktor, hipernapęd, osłony, kadłub) dostaje osobny wpis z PROGNOZĄ (pierwsze losowanie) i niezależnie
-- wylosowanym CZASEM RZECZYWISTYM (drugie losowanie). Stocznia ma kilka stanowisk pracujących równolegle
-- (api/floty.php, STOCZNIE); wolne stanowisko od razu bierze następny wpis z kolejki (FIFO). Gracz widzi prognozę;
-- po rzeczywistym końcu podzespół wraca do 100%.
--
-- Import w phpMyAdmin. Ponowny import jest bezpieczny (CREATE TABLE IF NOT EXISTS).

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS stocznia_naprawy (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  stocznia VARCHAR(40) NOT NULL,
  obiekt_id BIGINT UNSIGNED NOT NULL,
  podzespol VARCHAR(40) NOT NULL,
  od_wartosci TINYINT UNSIGNED NOT NULL,
  stan ENUM('kolejka','w_toku','gotowa','przerwana') NOT NULL DEFAULT 'kolejka',
  zgloszono_utc DATETIME NOT NULL,
  start_utc DATETIME NULL,
  koniec_utc DATETIME NULL,
  prognoza_s INT UNSIGNED NOT NULL,
  faktyczny_s INT UNSIGNED NOT NULL,
  zglaszajacy_login VARCHAR(64) NOT NULL DEFAULT '',
  KEY ix_naprawy_stan (stocznia, stan, zgloszono_utc, id),
  KEY ix_naprawy_obiekt (obiekt_id, stan)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

