-- =====================================================================
-- migracje/045_orbitalne_doki_kuat.sql
-- =====================================================================

-- Lokacje orbitalne i w przestrzeni; pierścień stoczniowy Kuat (Kuat Drive Yards Orbital Array) z dokami ISD.
--
-- lokalizacje: orbita_wysokosc_km + orbita_kat_deg (lokacja na orbicie planety) albo uklad_kx/ky (punkt
-- w przestrzeni układu, km od słońca). Pierścień: 1000 km nad Kuat (promień 6000 km, obwód ok. 37,699 km).
-- Gdyby cały obwód był dokami ISD (1,6 km + luz = 2 km na stanowisko), zmieściłoby się ok. 18,849 okrętów;
-- pierścień to jednak głównie fabryki, magazyny, mieszkania i terminale. Doki ciężkie: 24 sektory co 15°
-- (A–X), w każdym 25 stanowisk = 600: 360 budowanych ISD, 180 naprawianych, 60 wolnych.
--
-- mapa_obiekty.dok_*: okręt zadokowany na stanowisku (dok_do_utc — koniec lotu łukiem po orbicie do doku).
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE lokalizacje
  ADD COLUMN orbita_wysokosc_km DECIMAL(10,1) NULL,
  ADD COLUMN orbita_kat_deg DECIMAL(8,4) NULL,
  ADD COLUMN uklad_kx DECIMAL(16,1) NULL,
  ADD COLUMN uklad_ky DECIMAL(16,1) NULL;

ALTER TABLE mapa_obiekty
  ADD COLUMN dok_stanowisko_id BIGINT UNSIGNED NULL,
  ADD COLUMN dok_od_utc DATETIME NULL,
  ADD COLUMN dok_do_utc DATETIME NULL,
  ADD COLUMN dok_kat_start DECIMAL(8,3) NULL,
  ADD COLUMN dok_r_start_km DECIMAL(12,1) NULL;

CREATE TABLE IF NOT EXISTS stocznia_stanowiska (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  lokalizacja_id BIGINT UNSIGNED NOT NULL,
  sektor TINYINT UNSIGNED NOT NULL,
  numer TINYINT UNSIGNED NOT NULL,
  oznaczenie VARCHAR(12) NOT NULL,
  kat_deg DECIMAL(8,4) NOT NULL COMMENT 'miejsce na pierścieniu (0° = wschód, jak orbita_deg)',
  stan ENUM('budowa','naprawa','wolne') NOT NULL DEFAULT 'wolne',
  obiekt_id BIGINT UNSIGNED NULL COMMENT 'okręt gracza w doku',
  opis VARCHAR(200) NOT NULL DEFAULT '',
  postep TINYINT UNSIGNED NOT NULL DEFAULT 0,
  UNIQUE KEY uq_stanowisko (lokalizacja_id, sektor, numer),
  KEY ix_stanowisko_obiekt (obiekt_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @pl := (SELECT id FROM mapa_planety WHERE nazwa = 'Kuat' LIMIT 1);
SET @orbita := (SELECT id FROM lokalizacje WHERE planeta_id = @pl AND nazwa = 'Kuat — Orbita' LIMIT 1);
SELECT 'lokacja', 'baza', @orbita, NULL, @pl, 'Kuat Drive Yards Orbital Array', NULL, NULL, 1, 'aktywna',
  'Pierścień orbitalnych stoczni Kuat Drive Yards otaczający planetę: doki konstrukcyjne i naprawcze okrętów liniowych, fabryki, terminale.',
  1000.0, 0
FROM DUAL WHERE @pl IS NOT NULL
ON DUPLICATE KEY UPDATE orbita_wysokosc_km = VALUES(orbita_wysokosc_km), orbita_kat_deg = VALUES(orbita_kat_deg), publiczna = 1;
SET @pierscien := (SELECT id FROM lokalizacje WHERE planeta_id = @pl AND nazwa = 'Kuat Drive Yards Orbital Array' LIMIT 1);

DELETE FROM stocznia_stanowiska WHERE lokalizacja_id = @pierscien AND obiekt_id IS NULL;





VALUES ('v45-doki-kuat', 'Lokacje orbitalne, pierścień stoczniowy Kuat: 600 stanowisk')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/046_lot_atmosferyczny.sql
-- =====================================================================

-- Lot w atmosferze: trzeci parametr silnika (obok hipernapędu i napędu podświetlnego) i trasa nad powierzchnią.
--
-- mapa_naped_jednostki.atmosferyczna_kmh — prędkość w atmosferze (km/h). Lądowanie: wejście w atmosferę pod
-- miejscem okrętu na orbicie, potem lot po łuku wielkiego koła do lądowiska (choćby na drugą stronę planety).
-- Start: lot w atmosferze pod okręt macierzysty (prom) albo prosto w górę, potem wznoszenie na orbitę.
-- mapa_obiekty.atm_*: trwający lot — współrzędne geograficzne początku i końca, czas, rodzaj (ladowanie/start).
-- Mapa rysuje jednostkę na tarczy planety w miejscu lądowiska (widok z góry: półkula północna, południowa tak samo).
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_naped_jednostki
  ADD COLUMN atmosferyczna_kmh DECIMAL(8,1) NOT NULL DEFAULT 1000;

ALTER TABLE mapa_obiekty
  ADD COLUMN atm_rodzaj ENUM('ladowanie','start') NULL,
  ADD COLUMN atm_od_utc DATETIME NULL,
  ADD COLUMN atm_do_utc DATETIME NULL,
  ADD COLUMN atm_szer0 DECIMAL(8,4) NULL,
  ADD COLUMN atm_dl0 DECIMAL(9,4) NULL,
  ADD COLUMN atm_szer1 DECIMAL(8,4) NULL,
  ADD COLUMN atm_dl1 DECIMAL(9,4) NULL,
  ADD COLUMN atm_orbita_deg DECIMAL(8,3) NULL COMMENT 'miejsce na orbicie po starcie';

-- Prędkości atmosferyczne znanych klas (km/h).
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.atmosferyczna_kmh = 850 WHERE o.klasa LIKE '%Lambda%' OR o.nazwa LIKE '%Lambda%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.atmosferyczna_kmh = 1050 WHERE o.klasa LIKE '%YT-1300%' OR o.klasa LIKE '%YT-2400%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.atmosferyczna_kmh = 800 WHERE o.klasa LIKE '%Gozanti%' OR o.nazwa LIKE '%Gozanti%';
UPDATE mapa_naped_jednostki n JOIN mapa_obiekty o ON o.id = n.obiekt_id SET n.atmosferyczna_kmh = 1100 WHERE o.klasa LIKE '%Kom%rk%' OR o.nazwa LIKE '%Kom%rk%';

VALUES ('v46-lot-atmosferyczny', 'Lot w atmosferze: prędkość atmosferyczna i trasa nad powierzchnią')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/047_przelot_orbitalny.sql
-- =====================================================================

-- Przelot orbitalny: jeden mechanizm dla dokowania do pierścienia i powrotu promu do hangaru okrętu.
--
-- Jednostka ma sztywne miejsce na orbicie (orbita_deg + promień z podejścia). Przelot to lot łukiem po orbicie
-- (krótszą stroną planety) od miejsca startu (kąt, promień) do celu (kąt, promień) w czasie przelot_od → przelot_do;
-- na końcu: dok na stanowisku albo wejście do hangaru okrętu macierzystego. Przyciski to skróty — liczy się tak samo.
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN przelot_cel ENUM('dok','hangar','orbita') NULL,
  ADD COLUMN przelot_od_utc DATETIME NULL,
  ADD COLUMN przelot_do_utc DATETIME NULL,
  ADD COLUMN przelot_kat0 DECIMAL(8,3) NULL,
  ADD COLUMN przelot_r0_km DECIMAL(12,1) NULL,
  ADD COLUMN przelot_kat1 DECIMAL(8,3) NULL,
  ADD COLUMN przelot_r1_km DECIMAL(12,1) NULL;

-- Sztywne miejsce na orbicie dla jednostek bez niego (wcześniej mapa liczyła je z kursu i jednostka „skakała”).
UPDATE mapa_obiekty SET orbita_deg = MOD(COALESCE(kurs_deg, 90) + 180, 360)
WHERE orbita_deg IS NULL AND planeta_id IS NOT NULL AND typ IN ('statek','jednostka');

VALUES ('v47-przelot-orbitalny', 'Przelot orbitalny: dok i powrót promu jednym mechanizmem')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/048_gospodarka_kuat.sql
-- =====================================================================

-- Zręby gospodarki galaktycznej i obiekty tła Kuat z liniami dostaw (wygenerowane skryptem).
--
-- Wookieepedia: durastal = żelazo + węgiel + karwanium, lommit, meleenium, neutronium, zersium. Lommit: Dorvalla, Elom,
-- Ord Thoden; meleenium (i doonium, dolowit, kammris): Wadi Raffa; zersium: Nag Ubdur; tibanna: Bespin. Kuat (Legends):
-- powierzchnia to ogrody i posiadłości, 3,6 mld mieszkańców, setki milionów robotników na pierścieniu, fabryki AT-AT.
-- Reszta (producenci rud, węgla, paliwa, żywności, elektroniki…) — wygenerowana (gosp_produkcja.zrodlo).
--
-- Szacunek: ISD 35 mln t, budowa 2 lata, 360 w budowie → ok. 12 mln t durastali na dobę (18 hut na pierścieniu,
-- ruda ×1,3 + węgiel i dodatki stopowe), podzespoły z 24 fabryk, żywność dla 300 mln mieszkańców pierścienia i połowy
-- potrzeb powierzchni. Linie dostaw: częstotliwość = ładowność / zużycie na dobę. Razem 90 obiektów,
-- 432 linii, ok. 287 dostaw na dobę do Kuat.
--
-- Import w phpMyAdmin; ponowny import czyści i wpisuje dane gospodarki od nowa.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS gosp_towary (
  kod VARCHAR(40) NOT NULL PRIMARY KEY,
  nazwa VARCHAR(120) NOT NULL,
  kategoria VARCHAR(40) NOT NULL,
  ladownosc_t INT UNSIGNED NOT NULL COMMENT 'typowy ładunek jednego transportu',
  klasa_transportu VARCHAR(80) NOT NULL,
  zrodlo VARCHAR(80) NOT NULL DEFAULT 'wygenerowane'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS gosp_produkcja (
  planeta VARCHAR(160) NOT NULL,
  towar VARCHAR(40) NOT NULL,
  wydajnosc_t_doba INT UNSIGNED NOT NULL,
  zrodlo VARCHAR(80) NOT NULL DEFAULT 'wygenerowane',
  PRIMARY KEY (planeta, towar),
  KEY ix_gosp_produkcja_towar (towar)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS gosp_obiekty (
  id INT UNSIGNED NOT NULL PRIMARY KEY,
  planeta VARCHAR(160) NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  rodzaj VARCHAR(40) NOT NULL,
  miejsce ENUM('powierzchnia','pierscien') NOT NULL,
  szer DECIMAL(8,3) NULL,
  dl DECIMAL(8,3) NULL,
  kat_deg DECIMAL(8,3) NULL COMMENT 'miejsce na pierścieniu orbitalnym',
  opis VARCHAR(300) NOT NULL DEFAULT '',
  KEY ix_gosp_obiekty_planeta (planeta)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS gosp_zuzycie (
  obiekt_id INT UNSIGNED NOT NULL,
  towar VARCHAR(40) NOT NULL,
  t_doba DECIMAL(14,1) NOT NULL,
  PRIMARY KEY (obiekt_id, towar)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS gosp_linie (
  id INT UNSIGNED NOT NULL PRIMARY KEY,
  obiekt_id INT UNSIGNED NOT NULL,
  towar VARCHAR(40) NOT NULL,
  producent VARCHAR(160) NOT NULL COMMENT 'planeta producenta',
  t_doba DECIMAL(14,1) NOT NULL,
  ladownosc_t INT UNSIGNED NOT NULL,
  klasa VARCHAR(80) NOT NULL,
  odstep_s INT UNSIGNED NOT NULL COMMENT 'co ile wylatuje kolejny transport',
  predkosc_au_h DECIMAL(5,2) NOT NULL,
  postoj_h DECIMAL(4,1) NOT NULL COMMENT 'załadunek / rozładunek',
  faza DECIMAL(5,4) NOT NULL,
  KEY ix_gosp_linie_obiekt (obiekt_id),
  KEY ix_gosp_linie_producent (producent)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Planety z Wookieepedii, których nie było na mapie.
SET @nowe := (SELECT MAX(id) FROM mapa_planety);


DELETE FROM gosp_linie; DELETE FROM gosp_zuzycie; DELETE FROM gosp_obiekty; DELETE FROM gosp_produkcja; DELETE FROM gosp_towary;








VALUES ('v48-gospodarka-kuat', 'Gospodarka: towary, produkcja, obiekty tła Kuat i linie dostaw')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/049_ladowiska_obiektow_tla.sql
-- =====================================================================

-- Lądowiska przy obiektach tła gospodarki (kopalnie, zakłady, porty na powierzchni) — można tam wylądować promem.
--
-- Każdy obiekt tła na powierzchni dostaje lokację typu „ladowisko” w swoich współrzędnych geograficznych
-- (x/y km z szerokości i długości: x = dł/360 · π · średnica, y = szer/360 · π · średnica — odwrotnie niż
-- astro_wsp_lokacji), publiczną, i powiązanie gosp_obiekty.lokalizacja_id. Tam też lądują transporty NPC.
--
-- Import w phpMyAdmin (po 048). Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE gosp_obiekty ADD COLUMN lokalizacja_id BIGINT UNSIGNED NULL;

SELECT 'ladowisko', 'platforma', NULL, NULL, p.id, CONCAT('Lądowisko — ', o.nazwa),
  ROUND(o.dl / 360 * PI() * p.srednica, 3), ROUND(o.szer / 360 * PI() * p.srednica, 3), 1, 'aktywna',
  CONCAT('Lądowisko przy obiekcie: ', o.nazwa, '. ', o.opis)
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa = o.planeta
WHERE o.miejsce = 'powierzchnia' AND o.szer IS NOT NULL AND o.dl IS NOT NULL AND p.srednica > 0
ON DUPLICATE KEY UPDATE x_km = VALUES(x_km), y_km = VALUES(y_km), publiczna = 1, status = 'aktywna';

UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa = o.planeta
JOIN lokalizacje l ON l.planeta_id = p.id AND l.nazwa = CONCAT('Lądowisko — ', o.nazwa)
SET o.lokalizacja_id = l.id
WHERE o.miejsce = 'powierzchnia';

VALUES ('v49-ladowiska-obiektow-tla', 'Lądowiska przy obiektach tła gospodarki')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/050_gosp_rynek.sql
-- =====================================================================

-- Tabela skrótowa gospodarki galaktycznej: kto co produkuje i zużywa, za ile (obieg oficjalny, hurtowy).
--
-- gosp_rynek — jeden wiersz na planetę, towar i obieg: produkcja i zużycie (t/dobę), indeks ceny (1,00 = średnia
-- galaktyczna) i cena lokalna (kr/t), szczegółowość: „obiekty” (planeta opracowana: obiekty tła i linie dostaw)
-- albo „szacunek” (znany popyt / podaż bez obiektów). Z niej korzystają kolejne prompty planet i potem giełda.
-- gosp_towary.cena_bazowa_kr_t — średnia galaktyczna. gosp_linie.obieg — obieg kontraktu (na razie oficjalny hurt;
-- później szary i przemyt). Wzór ceny: narzedzia/gospodarka/rynek_050.py i PROMPT_PLANETA.md.
--
-- Import w phpMyAdmin (po 048 i 049). Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE gosp_towary ADD COLUMN cena_bazowa_kr_t DECIMAL(12,2) NOT NULL DEFAULT 100;
ALTER TABLE gosp_linie ADD COLUMN obieg VARCHAR(30) NOT NULL DEFAULT 'oficjalny_hurt';

CREATE TABLE IF NOT EXISTS gosp_rynek (
  planeta VARCHAR(160) NOT NULL,
  towar VARCHAR(40) NOT NULL,
  obieg VARCHAR(30) NOT NULL DEFAULT 'oficjalny_hurt',
  produkcja_t_doba DECIMAL(14,1) NOT NULL DEFAULT 0,
  zuzycie_t_doba DECIMAL(14,1) NOT NULL DEFAULT 0,
  cena_indeks DECIMAL(6,3) NOT NULL DEFAULT 1,
  cena_kr_t DECIMAL(12,2) NOT NULL DEFAULT 0,
  szczegolowosc ENUM('obiekty','szacunek') NOT NULL DEFAULT 'szacunek',
  zrodlo VARCHAR(80) NOT NULL DEFAULT 'wygenerowane',
  uwagi VARCHAR(300) NOT NULL DEFAULT '',
  zmieniono TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (planeta, towar, obieg),
  KEY ix_gosp_rynek_towar (towar, obieg)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

UPDATE gosp_towary SET cena_bazowa_kr_t = 40 WHERE kod = 'ruda_zelaza';
UPDATE gosp_towary SET cena_bazowa_kr_t = 30 WHERE kod = 'wegiel';
UPDATE gosp_towary SET cena_bazowa_kr_t = 220 WHERE kod = 'lommit';
UPDATE gosp_towary SET cena_bazowa_kr_t = 900 WHERE kod = 'karwanium';
UPDATE gosp_towary SET cena_bazowa_kr_t = 1400 WHERE kod = 'meleenium';
UPDATE gosp_towary SET cena_bazowa_kr_t = 1600 WHERE kod = 'zersium';
UPDATE gosp_towary SET cena_bazowa_kr_t = 5000 WHERE kod = 'neutronium';
UPDATE gosp_towary SET cena_bazowa_kr_t = 2500 WHERE kod = 'metale_rzadkie';
UPDATE gosp_towary SET cena_bazowa_kr_t = 1800 WHERE kod = 'tibanna';
UPDATE gosp_towary SET cena_bazowa_kr_t = 600 WHERE kod = 'paliwo';
UPDATE gosp_towary SET cena_bazowa_kr_t = 12000 WHERE kod = 'elektronika';
UPDATE gosp_towary SET cena_bazowa_kr_t = 350 WHERE kod = 'durastal';
UPDATE gosp_towary SET cena_bazowa_kr_t = 120 WHERE kod = 'zywnosc';
UPDATE gosp_towary SET cena_bazowa_kr_t = 30000 WHERE kod = 'luksus';

ON DUPLICATE KEY UPDATE produkcja_t_doba = VALUES(produkcja_t_doba), zuzycie_t_doba = VALUES(zuzycie_t_doba),
  cena_indeks = VALUES(cena_indeks), cena_kr_t = VALUES(cena_kr_t), szczegolowosc = VALUES(szczegolowosc), uwagi = VALUES(uwagi);

VALUES ('v50-gosp-rynek', 'Gospodarka: tabela skrótowa rynku, ceny bazowe, obieg linii')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/051_gospodarka_mattri.sql
-- =====================================================================

-- Mattri: szczegółowy model rolniczo-eksportowy. Kanon potwierdza położenie w Inner Rim;
-- brak wiarygodnych danych o klimacie, ludności, cyklach i gospodarce planety. Pozostałe liczby
-- oraz nazwy obiektów są szacunkami do gry. Żywność: 1,200,000 t/d, z czego dotychczasowe
-- kontrakty kuackie (~249,000 t/d) stanowią ok. 21% eksportu.
SET NAMES utf8mb4;

-- Wartości planetologiczne robocze (niekanoniczne): świat umiarkowany, rolniczy.
SELECT 1411,25.2,371,17.4,10400,'G' WHERE EXISTS (SELECT 1 FROM mapa_planety WHERE id=1411)
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT 1411,'lesna','niska','Umiarkowany świat rolniczy; wielkie pasy upraw i rozproszone ośrodki przetwórcze (model gry).'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Dostawcy referencyjni; źródła planet i wielkości podaży są szacunkiem, nie faktami kanonicznymi.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

-- Bezpieczne ponowne uruchomienie: sprzątane są wyłącznie rekordy Mattri.
DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mattri');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mattri');
DELETE FROM gosp_obiekty WHERE planeta='Mattri';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Jedna linia na każdą pozycję zużycia. Pojemność odpowiada typowemu ładunkowi;
-- przy małym popycie zmniejszamy statek tak, by dostawa następowała co około tydzień.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin + ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
       GREATEST(500,IF(q.t_doba < q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),
       q.klasa,ROUND(GREATEST(500,IF(q.t_doba < q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
       1.6,2.5,ROUND(MOD(q.obiekt_id*0.137+q.t_doba*0.0001,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
        CASE z.towar WHEN 'zywnosc' THEN 'Mattri' WHEN 'nawozy' THEN 'Foundry'
          WHEN 'maszyny_rolnicze' THEN 'Corellia' WHEN 'czesci_maszyn' THEN 'Kuat'
          WHEN 'paliwo' THEN 'Cassander' WHEN 'elektronika' THEN 'Alpheridies'
          WHEN 'durastal' THEN 'Mattri' END AS producent,
        t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+25
) q;
-- Lądowiska zgodne z migracją 049, z użyciem średnicy z cykli.
SELECT 'ladowisko','platforma',NULL,NULL,1411,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
LEFT JOIN planety_cykle c ON c.planeta_id=p.id WHERE o.planeta='Mattri' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN lokalizacje l ON l.planeta_id=1411 AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Mattri' AND o.miejsce='powierzchnia';

-- Rynek liczony z produkcji i sum zużycia obiektów, według wspólnego wzoru cenowego.
SELECT 'Mattri',x.towar,'oficjalny_hurt',x.prod,x.kons,
       ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
       ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
       'obiekty','wygenerowane','wartości z produkcji i zużycia obiektów; produkcja i dostawcy modelowi'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
        CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((
          SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
          FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta
          JOIN mapa_planety mp ON mp.nazwa='Mattri'
          WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0
        ),3000) END AS odl
 FROM (
   SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
   FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Mattri'
         UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Mattri') k
   LEFT JOIN gosp_produkcja p ON p.planeta='Mattri' AND p.towar=k.towar
   LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Mattri' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Pamięć o dostawcach towarów sprowadzanych przez Mattri; ceny liczone jak wyżej, status szacunkowy.
ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_mattri FROM gosp_obiekty WHERE planeta='Mattri';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mattri') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Mattri' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mattri');

-- =====================================================================
-- migracje/052_gospodarka_albrae_don.sql
-- =====================================================================

-- Albrae-Don: szczegółowy model luksusowego rzemiosła, przetwórstwa i tranzytu.
-- Źródła Wookieepedii: Albrae-Don leży w Sern sector w Colonies; Draeo-Kax jest miastem
-- planety, w pobliżu którego przebiega Pica Rim Pipeline. Brak wiarygodnych danych o klimacie,
-- ludności, cyklach i gospodarce; rozmiar świata, urbanizacja, wszystkie liczby i pozostałe
-- obiekty są szacunkami do gry. Produkcję towarów luksusowych korygujemy z 1,818,000 do
-- 240,000 t/d; kontrakt Kuat (900 t/d) to mały, wiarygodny wycinek eksportu.
SET NAMES utf8mb4;

-- Ustawienia robocze, niekanoniczne. Nazwa planety i ID pobierane są z mapy.
SELECT id,24.6,382,19.0,11800 FROM mapa_planety WHERE nazwa='Albrae-Don'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'miasto','wysoka','Świat handlowo-rzemieślniczy; Draeo-Kax i korytarz Pica Rim Pipeline stanowią oś modelowej gospodarki.'
FROM mapa_planety WHERE nazwa='Albrae-Don'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

-- Korekta wcześniejszego, losowego oszacowania podaży. Towar luksusowy pozostaje kategorią zbiorczą.
VALUES ('Albrae-Don','luksus',240000,'wygenerowane')
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

-- Ponowny import odtwarza tylko obiekty, zużycie i linie Albrae-Don.
DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Albrae-Don');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Albrae-Don');
DELETE FROM gosp_obiekty WHERE planeta='Albrae-Don';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Jedna linia dla każdej pozycji zużycia, z mniejszym statkiem przy niskim popycie.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.7,2.4,ROUND(MOD(q.obiekt_id*0.173+q.t_doba*0.001,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'zywnosc' THEN 'Foundry' WHEN 'paliwo' THEN 'Cassander'
   WHEN 'durastal' THEN 'Nubia' WHEN 'elektronika' THEN 'Alpheridies' WHEN 'luksus' THEN 'Albrae-Don' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+25
) q;

-- Lądowiska dla powierzchniowych obiektów, zgodne z migracją 049.
SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Albrae-Don' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Albrae-Don' AND o.miejsce='powierzchnia';

-- Rynek liczony z produkcji i zużycia obiektów oraz z odległości do najbliższego producenta.
SELECT 'Albrae-Don',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','sumy obiektowe; producent luksusu lokalny, import pozostaje szacunkiem'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Albrae-Don'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Albrae-Don'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Albrae-Don') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Albrae-Don' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Albrae-Don' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Pamięć o dostawcach zewnętrznych; nie nadpisuj planet już opracowanych szczegółowo.

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_albrae_don FROM gosp_obiekty WHERE planeta='Albrae-Don';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Albrae-Don') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Albrae-Don' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Albrae-Don');

-- =====================================================================
-- migracje/053_gospodarka_foundry.sql
-- =====================================================================

-- Foundry: przemysłowy świat produkcji, z istniejącą gałęzią rolnictwa przemysłowego i eksportu żywności.
-- Wookieepedia (Legends): Foundry leży w Koloniach, ma przemysłowy teren i stolicę Denus; przed wojnami
-- klonów działała tu produkcja droidów Techno Union, a w epoce Imperium wytwarzano TIE/LN i prototypy
-- okrętów. Planeta jest bogata w hfredium, kammris i dolovite. Wielkości produkcji, lokalizacje obiektów,
-- współrzędne powierzchni i bieżące linie są szacunkami gry. Żywność zmniejszona z losowych 2,118,000
-- do 1,400,000 t/d; istniejące dostawy Kuat od Foundry (~813,000 t/d) pozostają bez zmian.
SET NAMES utf8mb4;

SELECT id,23.7,361,21.0,11200 FROM mapa_planety WHERE nazwa='Foundry'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'miasto','wysoka','Przemysłowy świat z Denus jako centrum; złoża metali, kompleksy montażowe i modelowe strefy upraw pod osłonami.'
FROM mapa_planety WHERE nazwa='Foundry'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),ladownosc_t=VALUES(ladownosc_t),klasa_transportu=VALUES(klasa_transportu),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Podaż modelowa. Złoża metali są oparte na źródłach Legends; wydajności pozostają szacunkami.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Foundry');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Foundry');
DELETE FROM gosp_obiekty WHERE planeta='Foundry';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Dostawy do każdej pozycji zużycia. Producent lokalny oznacza dostawę wewnątrz systemu.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.7,2.4,ROUND(MOD(q.obiekt_id*0.113+q.t_doba*0.0007,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'nawozy' THEN 'Foundry' WHEN 'metale_rzadkie' THEN 'Foundry' WHEN 'durastal' THEN 'Foundry'
   WHEN 'podzespoly_tie' THEN 'Foundry' WHEN 'zywnosc' THEN 'Foundry' WHEN 'elektronika' THEN 'Alpheridies'
   WHEN 'paliwo' THEN 'Cassander' WHEN 'wegiel' THEN 'Mygeeto' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+28
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Foundry' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Foundry' AND o.miejsce='powierzchnia';

-- Tabela rynku Foundry jest dokładną sumą produkcji i zużycia obiektów; najbliższy producent wyznacza transport.
SELECT 'Foundry',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','sumy z modelowych obiektów; zasoby mineralne inspirowane Legends'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Foundry'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Foundry'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Foundry') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Foundry' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Foundry' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Otwarte wątki podaży do Foundry; nie obniżaj wcześniej szczegółowo opisanych planet do szacunków.

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_foundry FROM gosp_obiekty WHERE planeta='Foundry';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Foundry') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Foundry' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Foundry');

-- =====================================================================
-- migracje/054_gospodarka_corellia.sql
-- =====================================================================

-- Corellia: przemysł, stocznie, maszyny rolnicze i zaopatrzenie Coronet.
-- Źródła kanoniczne: Coronet City, Coronet Spaceport i przemysł stoczniowy; epoka Imperium
-- przekształciła część stoczni w produkcję wojskową. Dane Legends rozszerzają rolę CEC i układu
-- stoczni. Wykorzystano istniejącą hierarchię lokacji z migracji 034 (bez tworzenia miast na nowo).
-- Wydajności, zużycia, współrzędne powierzchni i szczegóły poszczególnych zakładów są modelowe.
SET NAMES utf8mb4;

-- Mapa ma już wartości 25 h / 329 dni / 11 000 km; dodaj cykle tylko wtedy, gdy brak wpisu.
SELECT id,doba,rok,22.0,NULLIF(srednica,0) FROM mapa_planety WHERE nazwa='Corellia'
ON DUPLICATE KEY UPDATE planeta_id=VALUES(planeta_id);
SELECT id,'miasto','wysoka','Gęsto zaludniony świat przemysłowy ze stoczniami, Coronet City i rozległym zapleczem produkcyjnym.'
FROM mapa_planety WHERE nazwa='Corellia'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),ladownosc_t=VALUES(ladownosc_t),klasa_transportu=VALUES(klasa_transportu),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Produkcja: duże serie maszyn i stoczniowych podzespołów; żywność obejmuje pasy rolne poza Coronet.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

-- Odtwarzaj wyłącznie rekordy gospodarcze Corellii. Istniejące lokacje mapy pozostają nienaruszone.
DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Corellia');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Corellia');
DELETE FROM gosp_obiekty WHERE planeta='Corellia';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Dostawcy dla linii: duże zakłady mają 2–3 źródła. Żywność jest dzielona między produkcję
-- lokalną oraz nadwyżki Mattri i Foundry; pozostałe towary mają wskazanego producenta.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar,q.producent),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.7,2.5,ROUND(MOD(q.obiekt_id*0.131+q.t_doba*0.0009,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,
  CASE WHEN z.towar='zywnosc' AND z.t_doba<20000 THEN z.t_doba ELSE z.t_doba*s.udzial END AS t_doba,
  s.producent,t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 JOIN (
  SELECT 'zywnosc' AS towar,'Corellia' AS producent,0.89 AS udzial UNION ALL
  SELECT 'zywnosc','Mattri',0.07 UNION ALL SELECT 'zywnosc','Foundry',0.04
  UNION ALL SELECT 'nawozy','Foundry',1 UNION ALL SELECT 'paliwo','Cassander',1
  UNION ALL SELECT 'elektronika','Alpheridies',1 UNION ALL SELECT 'durastal','Corellia',1
  UNION ALL SELECT 'metale_rzadkie','Foundry',1 UNION ALL SELECT 'wegiel','Mygeeto',1
  UNION ALL SELECT 'luksus','Albrae-Don',1 UNION ALL SELECT 'maszyny_rolnicze','Corellia',1
  UNION ALL SELECT 'czesci_maszyn','Corellia',1 UNION ALL SELECT 'komponenty_stoczniowe','Corellia',1
 ) s ON s.towar=z.towar
  WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+32
   AND (z.towar<>'zywnosc' OR z.t_doba>=20000 OR s.producent='Corellia')
) q;

-- Powierzchniowe lądowiska. Główne miasta i stocznie pozostają w istniejącej mapie lokacji 034.
SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Corellia' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Corellia' AND o.miejsce='powierzchnia';

-- Rynek liczony z sum obiektów, produkcji i najbliższego producenta.
SELECT 'Corellia',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','produkcja i zużycie modelowe; shipbuilding based on Corellian shipyard lore'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Corellia'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Corellia'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Corellia') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Corellia' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Corellia' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Pamięć sieci o dostawcach wykorzystywanych przez Corellię; INSERT IGNORE nie degraduje opisanych planet.

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_corellia FROM gosp_obiekty WHERE planeta='Corellia';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Corellia') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Corellia' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Corellia');

-- =====================================================================
-- migracje/055_gospodarka_alpheridies.sql
-- =====================================================================

-- Alpheridies: małe osady, centrum lokalne i rzemiosło czujników podczerwieni.
-- Legends: przy czerwonym karle Aber Miraluka rozwinęli percepcję niezależną od światła widzialnego;
-- występują góry i równiny, kilka niewielkich osiedli, a Wookieepedia nie wymienia głównych importów
-- ani eksportów. Z tego powodu elektronika eksportowa HOLOLINK jest małą, całkowicie modelową niszą
-- specjalistycznych przyrządów IR, nie twierdzeniem o kanonicznej gałęzi przemysłu. Historyczna
-- ludność 1 mln dotyczy Wielkiej Wojny Sithów (ok. 4000 BBY), nie jest przenoszona na 3 BBY.
-- Uwaga mapowa: mapa_seed.sql ma region=1, natomiast Legends lokuje Alpheridies w Expansion Region;
-- ta migracja nie zmienia istniejącego rekordu mapy.
-- Produkcję elektroniki z losowych 2,035,000 korygujemy do 12,000 t/d; istniejące linie odbiorców
-- (Kuat i nowe planety sieci) pozostają nietknięte.
SET NAMES utf8mb4;

-- Mapa ma dobę 21 h i rok 450 dni, ale średnicy brak. Cykle są jawną estymacją gry.
SELECT id,21,450,11.0,9400,'M' FROM mapa_planety WHERE nazwa='Alpheridies'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km),gwiazda_typ=VALUES(gwiazda_typ);
SELECT id,'skalista','niska','Góry, równiny i niewielkie osiedla; model HOLOLINK zakłada lokalne warsztaty przyrządów podczerwieni.'
FROM mapa_planety WHERE nazwa='Alpheridies'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

-- Urealnij losową podaż globalną; nie zmieniaj historycznych linii do odbiorców.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Alpheridies');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Alpheridies');
DELETE FROM gosp_obiekty WHERE planeta='Alpheridies';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Linie na każdą pozycję zużycia. Dla małego popytu wybrano jednego producenta.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.4,2.4,ROUND(MOD(q.obiekt_id*0.157+q.t_doba*0.004,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'zywnosc' THEN 'Alpheridies' WHEN 'elektronika' THEN 'Alpheridies'
   WHEN 'durastal' THEN 'Corellia' WHEN 'paliwo' THEN 'Cassander' WHEN 'luksus' THEN 'Albrae-Don' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+26
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Alpheridies' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Alpheridies' AND o.miejsce='powierzchnia';

-- Rynek szczegółowy według sum obiektów i dystansu do najbliższego producenta.
SELECT 'Alpheridies',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','lokalne obiekty; eksport przyrządów IR jest modelem gry, nie kanonicznym eksportem'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Alpheridies'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Alpheridies'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Alpheridies') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Alpheridies' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Alpheridies' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Zewnętrzni dostawcy dla niewielkiego importu lokalnego.

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_alpheridies FROM gosp_obiekty WHERE planeta='Alpheridies';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Alpheridies') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Alpheridies' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Alpheridies');

-- =====================================================================
-- migracje/056_gospodarka_cassander.sql
-- =====================================================================

-- Cassander: modelowy węzeł paliw i zaopatrzenia przy trasie Braxant Run.
-- Legends: Cassander był stolicą sektora Cassander, leży w Outer Rim/New Territories i przy Braxant Run;
-- nie ma źródła potwierdzającego złoża ani eksport paliwa. Dlatego wydobycie surowca paliwowego,
-- rafinacja, współrzędne obiektów i skala gospodarki są w całości modelem HOLOLINK, a nie kanonem.
-- Mapa projektu oznacza region=2 (Kolonie), co nie zgadza się z Legends; migracja mapy nie zmienia.
-- Produkcję paliwa z losowych 343,000 korygujemy do 170,000 t/d; dostawy dotychczasowych odbiorców
-- (Mattri, Albrae-Don, Foundry, Corellia i Alpheridies) pozostają bez zmian.
SET NAMES utf8mb4;

-- Mapa ma dobę 24 h i rok 365 dni; średnica jest estymacją gry.
SELECT id,24,365,18,10200 FROM mapa_planety WHERE nazwa='Cassander'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'miasto','wysoka','Modelowy węzeł administracyjny sektora i obsługi Braxant Run; rafinacja paliw jest rozwinięciem gospodarki gry.'
FROM mapa_planety WHERE nazwa='Cassander'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),ladownosc_t=VALUES(ladownosc_t),klasa_transportu=VALUES(klasa_transportu),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Podaż modelowa: rafinerie przerabiają 55 tys. t/d surowca na 47 tys. t/d paliwa.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Cassander');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Cassander');
DELETE FROM gosp_obiekty WHERE planeta='Cassander';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Dostawy do obiektów; popyt duży ma dwóch lub trzech dostawców, mały pojedynczego.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.6,2.5,ROUND(MOD(q.obiekt_id*0.149+q.t_doba*0.0003,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'surowiec_paliwowy' THEN 'Cassander' WHEN 'paliwo' THEN 'Cassander'
   WHEN 'zywnosc' THEN 'Cassander' WHEN 'durastal' THEN 'Corellia' WHEN 'elektronika' THEN 'Alpheridies'
   WHEN 'nawozy' THEN 'Foundry' WHEN 'luksus' THEN 'Albrae-Don' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+32
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Cassander' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Cassander' AND o.miejsce='powierzchnia';

-- Rynek Cassander liczony z produkcji i zużycia obiektów.
SELECT 'Cassander',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','model rafinacji i zużycia; paliwo nie jest kanonicznym eksportem Cassander'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Cassander'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Cassander'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Cassander') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Cassander' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Cassander' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Pamięć o dostawcach drobnych importów; nie nadpisuj szczegółowych wpisów planet.

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_cassander FROM gosp_obiekty WHERE planeta='Cassander';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Cassander') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Cassander' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Cassander');

-- =====================================================================
-- migracje/057_gospodarka_mygeeto.sql
-- =====================================================================

-- Mygeeto: lodowy, krystaliczny świat wydobywczy i węzeł dawnych interesów Banking Clan.
-- Kanon: zimny, zurbanizowany świat i miejsce bitwy o Mygeeto; Legends: bogate złoża kryształów,
-- kopalnie i związki z InterGalactic Banking Clan. Wydobycie nova crystal jest oparte na Legends.
-- Węgiel koksujący nie jest potwierdzonym zasobem planety: pozostaje modelowym paliwem stałym HOLOLINK,
-- aby zasilić istniejące linie do hut Foundry i Corellii (łącznie ok. 44 500 t/d). Wolumeny i obiekty są szacunkami.
SET NAMES utf8mb4;

SELECT id,18.0,312,19.0,11000 FROM mapa_planety WHERE nazwa='Mygeeto'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'lodowa','wysoka','Zimny, zurbanizowany świat kryształów. Kopalnie, zakłady sortowania i infrastruktura handlowa są modelowym rozwinięciem znanych złóż i historii Banking Clan.'
FROM mapa_planety WHERE nazwa='Mygeeto'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),kategoria=VALUES(kategoria),ladownosc_t=VALUES(ladownosc_t),klasa_transportu=VALUES(klasa_transportu),zrodlo=VALUES(zrodlo),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Węgiel to wcześniejszy szacunek generatora, skorygowany do skali faktycznie opisanych odbiorców.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mygeeto');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mygeeto');
DELETE FROM gosp_obiekty WHERE planeta='Mygeeto';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Linie dostaw do Mygeeto; producenci są zarejestrowani w gosp_produkcja.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.7,2.4,ROUND(MOD(q.obiekt_id*0.127+q.t_doba*0.0005,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'nawozy' THEN 'Foundry' WHEN 'metale_rzadkie' THEN 'Foundry'
   WHEN 'durastal' THEN 'Corellia' WHEN 'elektronika' THEN 'Alpheridies'
   WHEN 'paliwo' THEN 'Cassander' WHEN 'wegiel' THEN 'Mygeeto'
   WHEN 'zywnosc' THEN 'Mygeeto' WHEN 'luksus' THEN 'Albrae-Don' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+30
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Mygeeto' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Mygeeto' AND o.miejsce='powierzchnia';

-- Rynek: ceny wyliczane wg salda i odległości od najbliższego producenta.
SELECT 'Mygeeto',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','model obiektów; wydobycie kryształów oparte na Legends, węgiel modelowy'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Mygeeto'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Mygeeto'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Mygeeto') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Mygeeto' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Mygeeto' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Sieć pamięta dostawców. Węgiel występuje już jako odbiorca w Foundry i Corellii.
ON DUPLICATE KEY UPDATE
 produkcja_t_doba=IF(szczegolowosc='szacunek',VALUES(produkcja_t_doba),produkcja_t_doba),
 zuzycie_t_doba=IF(szczegolowosc='szacunek',VALUES(zuzycie_t_doba),zuzycie_t_doba),
 cena_indeks=IF(szczegolowosc='szacunek',VALUES(cena_indeks),cena_indeks),
 cena_kr_t=IF(szczegolowosc='szacunek',VALUES(cena_kr_t),cena_kr_t),
 uwagi=IF(szczegolowosc='szacunek',VALUES(uwagi),uwagi);

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_mygeeto FROM gosp_obiekty WHERE planeta='Mygeeto';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mygeeto') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Mygeeto' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Mygeeto');

-- =====================================================================
-- migracje/058_gospodarka_eriadu.sql
-- =====================================================================

-- Eriadu: górzysta twierdza Imperium, z modelowym przemysłem ciężkim i stoczniami.
-- Kanon: górzysty świat Outer Rim, imperialny ośrodek związany z Grand Moffem Tarkinem.
-- Legends: przemysł, prestiżowe stocznie i wydobycie lommite (kod towaru w HOLOLINK: lommit).
-- Konkretne zakłady, ich współrzędne i skala produkcji są modelowe. Mapa projektu ma region 5
-- (Środkowe Rubieże), choć źródła kanoniczne umieszczają Eriadu w Outer Rim; migracja nie zmienia mapy.
SET NAMES utf8mb4;

SELECT id,24.0,360,23.0,13490 FROM mapa_planety WHERE nazwa='Eriadu'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'miasto','wysoka','Górzysty, silnie zurbanizowany świat z imperialnym kompleksem władzy. Wydobycie lommite, przemysł ciężki i stocznie rozbudowano w modelu gry na podstawie Legends.'
FROM mapa_planety WHERE nazwa='Eriadu'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

-- Towary są już w słowniku: lommit (lommite), durastal, elektronika, komponenty stoczniowe i żywność.
-- Korekta szacunkowej podaży Mygeeto po migracji 057 pozostaje bez zmian; tu aktualizujemy tylko Eriadu.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Eriadu');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Eriadu');
DELETE FROM gosp_obiekty WHERE planeta='Eriadu';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Dla dużych odbiorców żywności podziel dostawy między Eriadu, Mattri i Foundry;
-- małe pobory obsługuje lokalna produkcja. Pozostałe towary mają jednego wskazanego producenta.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar,q.producent),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.8,2.5,ROUND(MOD(q.obiekt_id*0.137+q.t_doba*0.0006,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,
  CASE WHEN z.towar='zywnosc' AND z.t_doba<20000 THEN z.t_doba ELSE z.t_doba*s.udzial END AS t_doba,
  s.producent,t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 JOIN (
  SELECT 'zywnosc' AS towar,'Eriadu' AS producent,0.60 AS udzial UNION ALL
  SELECT 'zywnosc','Mattri',0.25 UNION ALL SELECT 'zywnosc','Foundry',0.15
  UNION ALL SELECT 'nawozy','Foundry',1 UNION ALL SELECT 'durastal','Eriadu',1
  UNION ALL SELECT 'lommit','Eriadu',1 UNION ALL SELECT 'wegiel','Mygeeto',1
  UNION ALL SELECT 'elektronika','Eriadu',1 UNION ALL SELECT 'komponenty_stoczniowe','Eriadu',1
  UNION ALL SELECT 'paliwo','Cassander',1 UNION ALL SELECT 'luksus','Albrae-Don',1
 ) s ON s.towar=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+35
  AND (z.towar<>'zywnosc' OR z.t_doba>=20000 OR s.producent='Eriadu')
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Eriadu' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Eriadu' AND o.miejsce='powierzchnia';

-- Rynek Eriadu liczony z produkcji i sum zużycia obiektów, według wspólnego wzoru cenowego.
SELECT 'Eriadu',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','model obiektów; lommite i stocznie oparte na Legends, pozostałe wolumeny wygenerowane'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Eriadu'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Eriadu'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Eriadu') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Eriadu' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Eriadu' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Pamięć o podaży lommite i o dostawcach importów; szczegółowych rynków nie degraduje.
ON DUPLICATE KEY UPDATE
 produkcja_t_doba=IF(szczegolowosc='szacunek',VALUES(produkcja_t_doba),produkcja_t_doba),
 zuzycie_t_doba=IF(szczegolowosc='szacunek',VALUES(zuzycie_t_doba),zuzycie_t_doba),
 cena_indeks=IF(szczegolowosc='szacunek',VALUES(cena_indeks),cena_indeks),
 cena_kr_t=IF(szczegolowosc='szacunek',VALUES(cena_kr_t),cena_kr_t),
 zrodlo=IF(szczegolowosc='szacunek',VALUES(zrodlo),zrodlo),
 uwagi=IF(szczegolowosc='szacunek',VALUES(uwagi),uwagi);

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_eriadu FROM gosp_obiekty WHERE planeta='Eriadu';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Eriadu') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Eriadu' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Eriadu');

-- =====================================================================
-- migracje/059_gospodarka_ord_mantell.sql
-- =====================================================================

-- Ord Mantell: przemysł odzysku, złomowiska, naprawy i transport lokalny.
-- Kanon: scrapyard i podziemne tunele górnicze są poświadczone w materiałach Star Wars.
-- Legends: rozległe Scraplands, złomowiska statków, zakład Junk Heap i zależność od importowanej żywności.
-- Konkretne obiekty, przepustowości, towary odzyskane i wielkości produkcji są szacunkami HOLOLINK.
-- Mapa projektu podaje region 1 (Światy Jądra), podczas gdy źródła lokują Ord Mantell w Mid Rim;
-- migracja nie zmienia mapy ani istniejących tras NPC.
SET NAMES utf8mb4;

SELECT id,doba,rok,17.0,NULLIF(srednica,0) FROM mapa_planety WHERE nazwa='Ord Mantell'
ON DUPLICATE KEY UPDATE doba_h=VALUES(doba_h),rok_dni=VALUES(rok_dni),nachylenie_osi_deg=VALUES(nachylenie_osi_deg),srednica_km=VALUES(srednica_km);
SELECT id,'miasto','wysoka','Świat osad i rozległych złomowisk z przemysłem odzysku i napraw. Działalność Scraplands i zakładu Junk Heap jest opisana w Legends; przepustowości w modelu gry.'
FROM mapa_planety WHERE nazwa='Ord Mantell'
ON DUPLICATE KEY UPDATE typ_planety=VALUES(typ_planety),urbanizacja=VALUES(urbanizacja),opis=VALUES(opis);

ON DUPLICATE KEY UPDATE nazwa=VALUES(nazwa),kategoria=VALUES(kategoria),ladownosc_t=VALUES(ladownosc_t),klasa_transportu=VALUES(klasa_transportu),zrodlo=VALUES(zrodlo),cena_bazowa_kr_t=VALUES(cena_bazowa_kr_t);

-- Eksport jest modelem odzysku: złom, metale, używane części i elektronika po sortowaniu oraz naprawie.
ON DUPLICATE KEY UPDATE wydajnosc_t_doba=VALUES(wydajnosc_t_doba),zrodlo=VALUES(zrodlo);

DELETE FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Ord Mantell');
DELETE FROM gosp_zuzycie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Ord Mantell');
DELETE FROM gosp_obiekty WHERE planeta='Ord Mantell';
SET @obj := (SELECT COALESCE(MAX(id),0) FROM gosp_obiekty);



-- Linie hurtowe. Ord Mantell sprowadza żywność i paliwo; odzyskane towary zasilają lokalne zakłady.
SET @lin := (SELECT COALESCE(MAX(id),0) FROM gosp_linie);
SELECT @lin+ROW_NUMBER() OVER (ORDER BY q.obiekt_id,q.towar),q.obiekt_id,q.towar,q.producent,q.t_doba,
 GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek)),q.klasa,
 ROUND(GREATEST(500,IF(q.t_doba<q.typowy_ladunek/7,ROUND(q.t_doba*7,-2),q.typowy_ladunek))/q.t_doba*86400),
 1.7,2.5,ROUND(MOD(q.obiekt_id*0.157+q.t_doba*0.0008,1),4),'oficjalny_hurt'
FROM (
 SELECT z.obiekt_id,z.towar,z.t_doba,
  CASE z.towar WHEN 'paliwo' THEN 'Cassander' WHEN 'zywnosc' THEN 'Mattri'
   WHEN 'elektronika' THEN 'Alpheridies' WHEN 'durastal' THEN 'Ord Mantell'
   WHEN 'zlom_przemyslowy' THEN 'Ord Mantell' WHEN 'czesci_uzywane' THEN 'Ord Mantell'
   WHEN 'czesci_maszyn' THEN 'Ord Mantell' WHEN 'wegiel' THEN 'Mygeeto' END AS producent,
  t.ladownosc_t AS typowy_ladunek,t.klasa_transportu AS klasa
 FROM gosp_zuzycie z JOIN gosp_towary t ON t.kod=z.towar
 WHERE z.obiekt_id BETWEEN @obj+1 AND @obj+30
) q;

SELECT 'ladowisko','platforma',NULL,NULL,p.id,CONCAT('Lądowisko — ',o.nazwa),
 ROUND(o.dl/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),
 ROUND(o.szer/360*PI()*COALESCE(NULLIF(c.srednica_km,0),NULLIF(p.srednica,0)),3),1,'aktywna',o.opis
FROM gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta LEFT JOIN planety_cykle c ON c.planeta_id=p.id
WHERE o.planeta='Ord Mantell' AND o.miejsce='powierzchnia'
ON DUPLICATE KEY UPDATE x_km=VALUES(x_km),y_km=VALUES(y_km),publiczna=1,status='aktywna';
UPDATE gosp_obiekty o JOIN mapa_planety p ON p.nazwa=o.planeta
JOIN lokalizacje l ON l.planeta_id=p.id AND l.nazwa=CONCAT('Lądowisko — ',o.nazwa)
SET o.lokalizacja_id=l.id WHERE o.planeta='Ord Mantell' AND o.miejsce='powierzchnia';

-- Rynek planety: saldo, obrót i najkrótsza odległość do aktywnego producenta według wspólnego wzoru cen.
SELECT 'Ord Mantell',x.towar,'oficjalny_hurt',x.prod,x.kons,
 ROUND(LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),3),
 ROUND(x.cena*LEAST(2.5,GREATEST(0.5,(1-0.30*(x.prod-x.kons)/NULLIF(x.prod+x.kons,0))*(1+0.00008*x.odl))),2),
 'obiekty','wygenerowane','model odzysku i napraw; złomowiska oparte na Legends, wolumeny wygenerowane'
FROM (
 SELECT a.towar,a.prod,a.kons,t.cena_bazowa_kr_t AS cena,
  CASE WHEN a.prod>0 THEN 0 ELSE COALESCE((SELECT MIN(SQRT(POW(mp.x-pp.x,2)+POW(mp.y-pp.y,2)))
   FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa=gp.planeta JOIN mapa_planety mp ON mp.nazwa='Ord Mantell'
   WHERE gp.towar=a.towar AND gp.wydajnosc_t_doba>0),3000) END AS odl
 FROM (
  SELECT k.towar,COALESCE(p.wydajnosc_t_doba,0) AS prod,COALESCE(z.kons,0) AS kons
  FROM (SELECT towar FROM gosp_produkcja WHERE planeta='Ord Mantell'
   UNION SELECT g.towar FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id WHERE o.planeta='Ord Mantell') k
  LEFT JOIN gosp_produkcja p ON p.planeta='Ord Mantell' AND p.towar=k.towar
  LEFT JOIN (SELECT g.towar,SUM(g.t_doba) AS kons FROM gosp_zuzycie g JOIN gosp_obiekty o ON o.id=g.obiekt_id
   WHERE o.planeta='Ord Mantell' GROUP BY g.towar) z ON z.towar=k.towar
 ) a JOIN gosp_towary t ON t.kod=a.towar
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba=VALUES(produkcja_t_doba),zuzycie_t_doba=VALUES(zuzycie_t_doba),cena_indeks=VALUES(cena_indeks),cena_kr_t=VALUES(cena_kr_t),szczegolowosc=VALUES(szczegolowosc),zrodlo=VALUES(zrodlo),uwagi=VALUES(uwagi);

-- Otwarta pamięć dostawców. Wpisy już opracowane szczegółowo pozostają bez zmian.
ON DUPLICATE KEY UPDATE
 produkcja_t_doba=IF(szczegolowosc='szacunek',VALUES(produkcja_t_doba),produkcja_t_doba),
 zuzycie_t_doba=IF(szczegolowosc='szacunek',VALUES(zuzycie_t_doba),zuzycie_t_doba),
 cena_indeks=IF(szczegolowosc='szacunek',VALUES(cena_indeks),cena_indeks),
 cena_kr_t=IF(szczegolowosc='szacunek',VALUES(cena_kr_t),cena_kr_t),
 zrodlo=IF(szczegolowosc='szacunek',VALUES(zrodlo),zrodlo),
 uwagi=IF(szczegolowosc='szacunek',VALUES(uwagi),uwagi);

ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- Kontrole po imporcie.
SELECT COUNT(*) AS obiekty_ord_mantell FROM gosp_obiekty WHERE planeta='Ord Mantell';
SELECT l.id,l.producent,l.towar FROM gosp_linie l LEFT JOIN gosp_produkcja p ON p.planeta=l.producent AND p.towar=l.towar WHERE l.obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Ord Mantell') AND p.planeta IS NULL;
SELECT l.id FROM gosp_linie l LEFT JOIN gosp_obiekty o ON o.id=l.obiekt_id WHERE o.id IS NULL;
SELECT o.id,o.nazwa FROM gosp_obiekty o LEFT JOIN lokalizacje l ON l.id=o.lokalizacja_id WHERE o.planeta='Ord Mantell' AND o.miejsce='powierzchnia' AND l.id IS NULL;
SELECT SUM(86400/odstep_s) AS dostawy_na_dobe FROM gosp_linie WHERE obiekt_id IN (SELECT id FROM gosp_obiekty WHERE planeta='Ord Mantell');

-- =====================================================================
-- migracje/060_gospodarka_korekta_producentow.sql
-- =====================================================================

-- Korekta po planetach 051–059: producenci, którzy nie nadążali za kontraktami, i przesadzona wydajność.
--
-- • Cassander, paliwo: kontrakty ok. 55 300 t/dobę przy wydajności 47 000 → 62 000 t/dobę (świat paliwowy).
-- • Mygeeto, węgiel: kontrakty ok. 117 900 t/dobę przy wydajności 62 000 → linie dla obiektów spoza Mygeeto
--   (Foundry, Corellia, Eriadu, Ord Mantell) przechodzą do najbliższego innego producenta węgla z wydajnością
--   co najmniej 100 000 t/dobę; Mygeeto zostaje ze swoimi kontraktami lokalnymi.
-- • Albrae-Don, towary luksusowe: 240 000 t/dobę przy popycie ok. 2 300 → 9 000 t/dobę.
-- Rynek tych wierszy przeliczony wspólnym wzorem (saldo i odległość do najbliższego producenta).
-- Dostawy lokalne (producent na tej samej planecie co obiekt) gra pokazuje jako lot w atmosferze — bez zmian w danych.
--
-- Import w phpMyAdmin po 051–059. Ponowny import jest bezpieczny.

SET NAMES utf8mb4;

UPDATE gosp_produkcja SET wydajnosc_t_doba = 62000 WHERE planeta = 'Cassander' AND towar = 'paliwo';
UPDATE gosp_produkcja SET wydajnosc_t_doba = 9000 WHERE planeta = 'Albrae-Don' AND towar = 'luksus';

-- Węgiel dla obiektów spoza Mygeeto: najbliższy inny producent (>= 100 000 t/dobę).
UPDATE gosp_linie l
JOIN gosp_obiekty o ON o.id = l.obiekt_id
JOIN mapa_planety op ON op.nazwa = o.planeta
SET l.producent = (
  SELECT gp.planeta FROM gosp_produkcja gp JOIN mapa_planety pp ON pp.nazwa = gp.planeta
  WHERE gp.towar = 'wegiel' AND gp.planeta <> 'Mygeeto' AND gp.wydajnosc_t_doba >= 100000
  ORDER BY POW(pp.x - op.x, 2) + POW(pp.y - op.y, 2) LIMIT 1)
WHERE l.towar = 'wegiel' AND l.producent = 'Mygeeto' AND o.planeta <> 'Mygeeto';

-- Przeliczenie rynku dla poprawionych producentów (wzór jak w 050–059).
SELECT x.planeta, x.towar, 'oficjalny_hurt', x.prod, x.kons,
       ROUND(LEAST(2.5, GREATEST(0.5, (1 - 0.30 * (x.prod - x.kons) / NULLIF(x.prod + x.kons, 0)))), 3),
       ROUND(x.cena * LEAST(2.5, GREATEST(0.5, (1 - 0.30 * (x.prod - x.kons) / NULLIF(x.prod + x.kons, 0)))), 2),
       x.szcz, 'wygenerowane', 'korekta 060: wydajność dopasowana do kontraktów'
FROM (
  SELECT gp.planeta, gp.towar, gp.wydajnosc_t_doba AS prod, t.cena_bazowa_kr_t AS cena,
         COALESCE((SELECT SUM(z.t_doba) FROM gosp_zuzycie z JOIN gosp_obiekty o ON o.id = z.obiekt_id WHERE o.planeta = gp.planeta AND z.towar = gp.towar), 0) AS kons,
         IF(EXISTS (SELECT 1 FROM gosp_obiekty o WHERE o.planeta = gp.planeta), 'obiekty', 'szacunek') AS szcz
  FROM gosp_produkcja gp JOIN gosp_towary t ON t.kod = gp.towar
  WHERE (gp.planeta, gp.towar) IN (('Cassander','paliwo'), ('Albrae-Don','luksus'), ('Mygeeto','wegiel'))
) x
ON DUPLICATE KEY UPDATE produkcja_t_doba = VALUES(produkcja_t_doba), zuzycie_t_doba = VALUES(zuzycie_t_doba),
  cena_indeks = VALUES(cena_indeks), cena_kr_t = VALUES(cena_kr_t), uwagi = VALUES(uwagi);

VALUES ('v60-gospodarka-korekta', 'Gospodarka: korekta producentów po planetach 051–059')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- Kontrola: producenci z kontraktami powyżej wydajności (powinno być pusto) i nowi dostawcy węgla.
SELECT l.producent, l.towar, ROUND(SUM(l.t_doba)) AS kontrakty, p.wydajnosc_t_doba
FROM gosp_linie l JOIN gosp_produkcja p ON p.planeta = l.producent AND p.towar = l.towar
GROUP BY l.producent, l.towar, p.wydajnosc_t_doba HAVING SUM(l.t_doba) > p.wydajnosc_t_doba;
SELECT o.planeta, l.producent, ROUND(SUM(l.t_doba)) AS wegiel_t_doba FROM gosp_linie l JOIN gosp_obiekty o ON o.id = l.obiekt_id
WHERE l.towar = 'wegiel' AND o.planeta IN ('Foundry','Corellia','Eriadu','Ord Mantell','Mygeeto') GROUP BY o.planeta, l.producent;

-- =====================================================================
-- migracje/060_stocznia_naprawy.sql
-- =====================================================================

-- Stocznia naprawcza (Kuat): kolejka napraw podzespołów okrętów.
--
-- Gracz przy Kuat oddaje okręt do naprawy; wpisy pracują równolegle i FIFO.
-- Import jest bezpieczny przy ponowieniu dzięki CREATE TABLE IF NOT EXISTS.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS stocznia_naprawy (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  stocznia VARCHAR(40) NOT NULL,
  obiekt_id BIGINT UNSIGNED NOT NULL,
  podzespol VARCHAR(40) NOT NULL,
  od_wartosci TINYINT UNSIGNED NOT NULL,
  stan ENUM('kolejka','w_toku','gotowa','przerwana') NOT NULL DEFAULT 'kolejka',
  zgloszono_utc DATETIME NOT NULL,
  start_utc DATETIME NULL,
  koniec_utc DATETIME NULL,
  prognoza_s INT UNSIGNED NOT NULL,
  faktyczny_s INT UNSIGNED NOT NULL,
  zglaszajacy_login VARCHAR(64) NOT NULL DEFAULT '',
  KEY ix_naprawy_stan (stocznia, stan, zgloszono_utc, id),
  KEY ix_naprawy_obiekt (obiekt_id, stan)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- =====================================================================
-- migracje/061_isd_i_planety_poboczne.sql
-- =====================================================================

-- Garnizony imperialne na pobocznych planetach pozostających pod kontrolą Imperium.
-- Wybrane planety: Tatooine, Lothal, Foundry i Mygeeto.
-- Nar Shaddaa i Ord Mantell (światy przemytnicze) są pominięte.
-- Wymaga migracji 009_flota_dromund_kaas.sql oraz tabel mapa_planety, mapa_floty,
-- mapa_obiekty, mapa_floty_jednostki, mapa_naped_jednostki, podmioty i osoby.
-- Można uruchamiać ponownie: stałe kody zapobiegają duplikatom.

SET NAMES utf8mb4;

DROP TEMPORARY TABLE IF EXISTS tmp_isd_garnizony;
CREATE TEMPORARY TABLE tmp_isd_garnizony (
  planeta VARCHAR(120) NOT NULL PRIMARY KEY,
  kod VARCHAR(80) NOT NULL,
  nazwa_okretu VARCHAR(160) NOT NULL,
  kod_floty VARCHAR(80) NOT NULL,
  nazwa_floty VARCHAR(160) NOT NULL,
  kapitan VARCHAR(160) NOT NULL
) ENGINE=MEMORY;


SELECT 'osoba', g.kapitan
FROM tmp_isd_garnizony g
WHERE NOT EXISTS (
  SELECT 1 FROM podmioty p
  WHERE p.typ='osoba'
    AND p.nazwa COLLATE utf8mb4_unicode_ci = g.kapitan COLLATE utf8mb4_unicode_ci
);

SELECT p.id,'kapitan imperialnej floty','zdrowy','brak'
FROM tmp_isd_garnizony g
JOIN podmioty p ON p.typ='osoba'
  AND p.nazwa COLLATE utf8mb4_unicode_ci = g.kapitan COLLATE utf8mb4_unicode_ci
LEFT JOIN osoby o ON o.podmiot_id=p.id
WHERE o.podmiot_id IS NULL;

SELECT g.kod_floty,g.nazwa_floty,NULL,p.id,
       CONCAT('Imperialny garnizon planetarny z okrętem flagowym ',g.nazwa_okretu,
              ', pod dowództwem ',g.kapitan,'.')
FROM tmp_isd_garnizony g
JOIN podmioty p ON p.typ='osoba'
  AND p.nazwa COLLATE utf8mb4_unicode_ci = g.kapitan COLLATE utf8mb4_unicode_ci
ON DUPLICATE KEY UPDATE
  nazwa=VALUES(nazwa),
  dowodca_osoba_id=COALESCE(mapa_floty.dowodca_osoba_id,VALUES(dowodca_osoba_id)),
  status=IF(mapa_floty.status='nieaktywna','aktywna',mapa_floty.status),
  opis=COALESCE(mapa_floty.opis,VALUES(opis));

SELECT g.kod,'statek',g.nazwa_okretu,'okręt','ISD I','Imperium','sprawny',p.id,
       p.x+10,p.y+10,'#00ff66','trojkat',
       CONCAT('Okręt flagowy imperialnego garnizonu planety ',g.planeta,'.'),1
FROM tmp_isd_garnizony g
JOIN mapa_planety p
  ON p.nazwa COLLATE utf8mb4_unicode_ci = g.planeta COLLATE utf8mb4_unicode_ci;

SELECT o.id,f.id,'okręt flagowy',0,NULL
FROM tmp_isd_garnizony g
JOIN mapa_obiekty o
  ON o.kod COLLATE utf8mb4_unicode_ci = g.kod COLLATE utf8mb4_unicode_ci
JOIN mapa_floty f
  ON f.kod COLLATE utf8mb4_unicode_ci = g.kod_floty COLLATE utf8mb4_unicode_ci;

SELECT o.id
FROM tmp_isd_garnizony g
JOIN mapa_obiekty o
  ON o.kod COLLATE utf8mb4_unicode_ci = g.kod COLLATE utf8mb4_unicode_ci;

VALUES ('v60-isd-planety-poboczne','Imperialne ISD I z kapitanami NPC na Tatooine, Lothal, Foundry i Mygeeto');

DROP TEMPORARY TABLE IF EXISTS tmp_isd_garnizony;

-- =====================================================================
-- migracje/062_poparcie_stronnictw_planety.sql
-- =====================================================================

-- Szacunkowe poparcie polityczne na planetach, stan świata gry: 3 BBY.
-- Wartości są udziałami procentowymi (0–100) i sumują się do 100 dla każdego
-- opisanego świata. Źródła opisują kontrolę, nastroje i aktywność frakcji, nie
-- podają sondaży; liczby są więc modelem HOLOLINK, a nie danymi kanonicznymi.
-- Pozostałe planety pozostają NULL do czasu ustalenia wiarygodnych przesłanek.
-- Frakcje są celowo zagregowane: Imperium, Rebelia, Syndykat.

SET NAMES utf8mb4;

SET @ddl := IF(
  EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='mapa_planety' AND COLUMN_NAME='poparcie_imperium_pct'),
  'SELECT 1',
  'ALTER TABLE mapa_planety ADD COLUMN poparcie_imperium_pct DECIMAL(5,2) NULL COMMENT ''Szacunkowe poparcie Imperium w procentach (model gry, 3 BBY)'''
);
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @ddl := IF(
  EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='mapa_planety' AND COLUMN_NAME='poparcie_rebelia_pct'),
  'SELECT 1',
  'ALTER TABLE mapa_planety ADD COLUMN poparcie_rebelia_pct DECIMAL(5,2) NULL COMMENT ''Szacunkowe poparcie Rebelii w procentach (model gry, 3 BBY)'''
);
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @ddl := IF(
  EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='mapa_planety' AND COLUMN_NAME='poparcie_syndykat_pct'),
  'SELECT 1',
  'ALTER TABLE mapa_planety ADD COLUMN poparcie_syndykat_pct DECIMAL(5,2) NULL COMMENT ''Szacunkowe poparcie Syndykatu w procentach (model gry, 3 BBY)'''
);
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

UPDATE mapa_planety p
JOIN (
  SELECT 'Alderaan' AS nazwa, 10.00 AS imperium, 85.00 AS rebelia, 5.00 AS syndykat UNION ALL
  SELECT 'Corellia', 35.00, 50.00, 15.00 UNION ALL
  SELECT 'Coruscant', 80.00, 15.00, 5.00 UNION ALL
  SELECT 'Dromund Kaas', 80.00, 15.00, 5.00 UNION ALL
  SELECT 'Eriadu', 70.00, 20.00, 10.00 UNION ALL
  SELECT 'Foundry', 70.00, 20.00, 10.00 UNION ALL
  SELECT 'Havis III', 80.00, 10.00, 10.00 UNION ALL
  SELECT 'Kessel', 25.00, 10.00, 65.00 UNION ALL
  SELECT 'Kuat', 80.00, 15.00, 5.00 UNION ALL
  SELECT 'Lothal', 30.00, 60.00, 10.00 UNION ALL
  SELECT 'Mygeeto', 20.00, 70.00, 10.00 UNION ALL
  SELECT 'Nal Hutta', 5.00, 5.00, 90.00 UNION ALL
  SELECT 'Naboo', 70.00, 25.00, 5.00 UNION ALL
  SELECT 'Nar Shaddaa', 5.00, 10.00, 85.00 UNION ALL
  SELECT 'Ord Mantell', 20.00, 20.00, 60.00 UNION ALL
  SELECT 'Tatooine', 10.00, 10.00, 80.00 UNION ALL
  SELECT 'Zephyria', 80.00, 10.00, 10.00
) s ON s.nazwa=p.nazwa
SET p.poparcie_imperium_pct=s.imperium,
    p.poparcie_rebelia_pct=s.rebelia,
    p.poparcie_syndykat_pct=s.syndykat;

VALUES ('v62-poparcie-stronnictw-planet','Szacunkowe poparcie Imperium, Rebelii i Syndykatu na planetach (3 BBY)')
ON DUPLICATE KEY UPDATE opis=VALUES(opis);

-- =====================================================================
-- migracje/063_rozrzut_ukladow_severiana.sql
-- =====================================================================

-- Nieregularne pozycje 12 systemów Nowej Rebelii pomiędzy Eriadu i Kabal.
-- Współrzędne wynikają z ustalonego rozrzutu pseudolosowego (ziarno 22112026),
-- zapisanego jako udziały prostokąta Eriadu–Kabal. Import jest powtarzalny:
-- ponowienie wylicza te same pozycje i nie kumuluje przesunięcia obiektów.
-- Każdy rekord jest osobnym systemem z jedną gwiazdą; nie są księżycami Eriadu.

SET NAMES utf8mb4;
DROP TEMPORARY TABLE IF EXISTS tmp_severiana_scatter;
DROP TEMPORARY TABLE IF EXISTS tmp_severiana_positions;

CREATE TEMPORARY TABLE tmp_severiana_scatter (
  nazwa VARCHAR(120) NOT NULL PRIMARY KEY,
  fx DECIMAL(7,4) NOT NULL,
  fy DECIMAL(7,4) NOT NULL
) ENGINE=MEMORY DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;


CREATE TEMPORARY TABLE tmp_severiana_positions ENGINE=MEMORY AS
SELECT p.id AS planeta_id,p.x AS stare_x,p.y AS stare_y,
       ROUND(e.x+d.fx*(k.x-e.x),1) AS nowe_x,
       ROUND(e.y+d.fy*(k.y-e.y),1) AS nowe_y
FROM mapa_planety p
JOIN tmp_severiana_scatter d
  ON p.nazwa COLLATE utf8mb4_unicode_ci=d.nazwa COLLATE utf8mb4_unicode_ci
JOIN mapa_planety e
  ON e.nazwa COLLATE utf8mb4_unicode_ci='Eriadu' COLLATE utf8mb4_unicode_ci
JOIN mapa_planety k
  ON k.nazwa COLLATE utf8mb4_unicode_ci='Kabal' COLLATE utf8mb4_unicode_ci;

START TRANSACTION;

-- Przesuń obiekty znajdujące się przy tych światach razem z układami.
UPDATE mapa_obiekty o
JOIN tmp_severiana_positions d ON d.planeta_id=o.planeta_id
SET o.x=o.x+(d.nowe_x-d.stare_x),
    o.y=o.y+(d.nowe_y-d.stare_y),
    o.lot_start_x=IF(o.lot_start_x IS NULL,NULL,o.lot_start_x+(d.nowe_x-d.stare_x)),
    o.lot_start_y=IF(o.lot_start_y IS NULL,NULL,o.lot_start_y+(d.nowe_y-d.stare_y));

-- Jeśli system jest celem trwającego lotu, przesuń także punkt końcowy trajektorii.
UPDATE mapa_obiekty o
JOIN tmp_severiana_positions d ON d.planeta_id=o.lot_cel_planeta_id
SET o.lot_cel_x=o.lot_cel_x+(d.nowe_x-d.stare_x),
    o.lot_cel_y=o.lot_cel_y+(d.nowe_y-d.stare_y);

-- Niezależne, nieregularne systemy gwiezdne w korytarzu pomiędzy Eriadu i Kabal.
UPDATE mapa_planety p
JOIN tmp_severiana_positions d ON d.planeta_id=p.id
SET p.x=d.nowe_x,p.y=d.nowe_y,p.slonca=1;

VALUES ('v63-rozrzut-ukladow-severiana','Nieregularne pozycje 12 systemów Nowej Rebelii pomiędzy Eriadu i Kabal')
ON DUPLICATE KEY UPDATE opis=VALUES(opis);

COMMIT;
DROP TEMPORARY TABLE IF EXISTS tmp_severiana_positions;
DROP TEMPORARY TABLE IF EXISTS tmp_severiana_scatter;

-- =====================================================================
-- migracje/064_loty_lukowe_antykolizyjne.sql
-- =====================================================================

-- Zapis trasy lotu podświetlnego jako punktów stycznych omijających planety i gwiazdy.
-- Dzięki temu mapa, pokład i przerwanie lotu korzystają z tej samej krzywej.
SET NAMES utf8mb4;

ALTER TABLE mapa_obiekty
  ADD COLUMN lot_trasa_json MEDIUMTEXT NULL AFTER lot_cel_ky;

VALUES ('v64-loty-lukowe-antykolizyjne', 'Trasy lotów podświetlnych omijają ciała układu łukiem')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/065_szyk_floty.sql
-- =====================================================================

-- Szyk floty: okręty mają stałe miejsca względem prowadzącego (pierwszy według mapa_floty_jednostki.kolejnosc).
--
-- mapa_floty.szyk — 'obronny' (pierścienie wokół prowadzącego: 6, 12, 18… miejsc co odstęp),
--   'eskortowy' (klin za prowadzącym), 'linia' (szereg w poprzek kursu); NULL — bez szyku (dawny wachlarz).
-- mapa_floty.szyk_odstep_km — odstęp między miejscami szyku (domyślnie 8 km).
-- Na mapie flota jest jednym trójkątem, dopóki odstęp na ekranie nie przekroczy ok. 12 px; potem każdy okręt
-- stoi w swoim miejscu (kierunek szyku = kurs prowadzącego).
--
-- Flota Eskortowa Havis III: średnia orbita Havis III, szyk obronny co 8 km — Arquitens 1 prowadzi,
-- Arquitens 2 i Gozanti 1–5 w pierwszym pierścieniu, Gozanti 6 w drugim.
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

ALTER TABLE mapa_floty
  ADD COLUMN szyk VARCHAR(20) NULL,
  ADD COLUMN szyk_odstep_km DECIMAL(8,2) NULL;

-- Domyślny szyk flot obronnych i eskortowych.
UPDATE mapa_floty SET szyk = 'obronny', szyk_odstep_km = 8
WHERE szyk IS NULL AND (nazwa LIKE '%Eskort%' OR nazwa LIKE '%Obron%');

-- Kolejność w szyku Floty Eskortowej Havis III.
UPDATE mapa_floty_jednostki j
JOIN mapa_obiekty o ON o.id = j.obiekt_id
JOIN mapa_floty f ON f.id = j.flota_id AND f.kod = 'havis-iii-eskortowa'
SET j.kolejnosc = CASE o.kod
    WHEN 'havis-arquitens-01' THEN 0
    WHEN 'havis-arquitens-02' THEN 1
    ELSE 1 + CAST(RIGHT(o.kod, 2) AS UNSIGNED) END;

-- Średnia orbita Havis III, wspólne miejsce na orbicie (bez jednostek w nadprzestrzeni, na lądowisku i w hangarze).
UPDATE mapa_obiekty o
JOIN mapa_floty_jednostki j ON j.obiekt_id = o.id
JOIN mapa_floty f ON f.id = j.flota_id AND f.kod = 'havis-iii-eskortowa'
JOIN mapa_planety p ON p.nazwa = 'Havis III'
LEFT JOIN mapa_rozkazy_skokow_jednostki r ON r.obiekt_id = o.id AND r.status = 'w_nadprzestrzeni'
SET o.planeta_id = p.id, o.x = p.x, o.y = p.y, o.podejscie = 'srednia', o.orbita_deg = 90, o.kurs_deg = 0,
    o.podlot_start = NULL, o.podlot_cel = NULL, o.podlot_od_utc = NULL, o.podlot_do_utc = NULL,
    o.kurs_start_deg = NULL, o.kurs_cel_deg = NULL, o.manewr_od_utc = NULL, o.manewr_do_utc = NULL
WHERE r.obiekt_id IS NULL AND o.ladowisko_id IS NULL AND COALESCE(o.w_hangarze, 0) = 0;

VALUES ('v065-szyk-floty', 'Szyk floty (obronny, eskortowy, linia); Flota Eskortowa Havis III na średniej orbicie')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/066_klucze_mysliwcow.sql
-- =====================================================================

-- Klucze myśliwców i promów (api/klucze.php): klucz = 4 maszyny z hangaru okrętu, jeden mały trójkąt na mapie.
--
-- mapa_klucze — klucz w locie: okręt macierzysty, numer, rodzaj (tie / lambda), rozkaz i cel, trasa zaplanowana
--   przez serwer (trasa_json: [[czas gry, km od słońca x, y], …]) i faza przy celu (po_cel_id, po_promien_km —
--   krążenie wokół celu po dolocie), prędkość, chwila startu z taśmociągu. Po powrocie do hangaru wiersz znika.
-- mapa_floty_jednostki.lambda_liczba — promy Lambda w hangarze (klucz = 4); ISD: 4. Myśliwce — tie_liczba.
--
-- Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — wtedy wystarczy reszta pliku.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS mapa_klucze (
  id INT AUTO_INCREMENT PRIMARY KEY,
  okret_id INT NOT NULL,
  numer SMALLINT NOT NULL,
  rodzaj VARCHAR(10) NOT NULL DEFAULT 'tie',
  maszyny TINYINT NOT NULL DEFAULT 4,
  uklad_x DECIMAL(10,1) NOT NULL,
  uklad_y DECIMAL(10,1) NOT NULL,
  rozkaz VARCHAR(20) NOT NULL DEFAULT 'patrol',
  cel_obiekt_id INT NULL,
  po_cel_id INT NULL,
  po_promien_km DECIMAL(10,2) NOT NULL DEFAULT 0,
  trasa_json MEDIUMTEXT NOT NULL,
  predkosc_kms DECIMAL(10,1) NOT NULL,
  start_utc DATETIME NOT NULL,
  rozkaz_utc DATETIME NOT NULL,
  KEY okret (okret_id),
  KEY cel (cel_obiekt_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE mapa_floty_jednostki ADD COLUMN lambda_liczba SMALLINT NULL;

UPDATE mapa_floty_jednostki j JOIN mapa_obiekty o ON o.id = j.obiekt_id
SET j.lambda_liczba = 4
WHERE j.lambda_liczba IS NULL AND (o.klasa LIKE 'ISD%' OR o.klasa LIKE '%Star Destroyer%');

VALUES ('v066-klucze-mysliwcow', 'Klucze myśliwców i promów Lambda: start z hangaru, rozkazy, trasy liczone przez serwer')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/067_piloci_skan.sql
-- =====================================================================

-- Piloci okrętów i skan z bliska kluczami myśliwców (api/klucze.php).
--
-- mapa_piloci — piloci na pokładzie okrętu (2 na maszynę z hangaru: TIE i Lambdy; ISD 72 TIE + 4 Lambdy = 152),
--   generowani przy pierwszym otwarciu hangaru: imię, ranga (as ok. 5%, standard 60%, kadet 35%), doświadczenie
--   (globalne dla pilota; mnożnik zdobywania: as ×0,5, standardowy ×1, kadet ×1,5), klucz, w którym leci.
-- mapa_klucze.rozkaz_login — konto, które wydało rozkaz (do niego trafia wynik skanu jako identyfikacja radaru),
--   skan_stan ('trwa' / 'udany' / 'nieudany') i skan_opis (prawdziwa nazwa, ładunek, trasa).
--
-- Wymaga migracji 066. Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — reszta jest już w bazie.

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS mapa_piloci (
  id INT AUTO_INCREMENT PRIMARY KEY,
  okret_id INT NOT NULL,
  numer SMALLINT NOT NULL,
  imie VARCHAR(80) NOT NULL,
  ranga VARCHAR(10) NOT NULL DEFAULT 'standard',
  xp INT NOT NULL DEFAULT 0,
  klucz_id INT NULL,
  UNIQUE KEY okret_numer (okret_id, numer),
  KEY klucz (klucz_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE mapa_klucze
  ADD COLUMN rozkaz_login VARCHAR(64) NULL,
  ADD COLUMN skan_stan VARCHAR(12) NULL,
  ADD COLUMN skan_opis VARCHAR(255) NULL;

VALUES ('v067-piloci-skan', 'Piloci okrętów (asy, standardowi, kadeci, doświadczenie) i skan z bliska kluczami myśliwców')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/068_bitwy_symulacje.sql
-- =====================================================================

-- Bitwy i symulacje bitew (mechanika: narzedzia/mostek/MECHANIKA.md, wdrożenie: narzedzia/mostek/WDROZENIE.md).
--
-- Jeden silnik dla obu rodzajów bitwy. mapa_bitwy.rodzaj = 'symulacja' (instancja: stan tylko w tabelach bitwy_*,
-- nic nie wraca do świata poza XP pilotów) albo 'rzeczywista' (później: skutki zapisywane w świecie).
-- Symulacja ma planeta_id = NULL — dzięki temu nie pojawia się na radarze ani w spisie bitew planety.
--
-- Słowniki mechaniki (wypełnia migracja 069, generowana z narzedzia/mostek/):
--   mechanika_stale        — stałe wspólne (tik, cykl, porcje, Hz odniesienia, wykładnik zużycia…)
--   profile_klas (+ _jednostki, _sektory, _kadlub) — profile klas okrętów (ISD_I, MC80, ZBIEG)
--   typy_maszyn            — myśliwce i promy: Hz bazowe, osłona, prędkość, przekrój, energia strzału
--   rozkazy_profile        — czas wykonania rozkazów: przygotowanie, działanie, odnowienie, mnożniki rozrzutu
--   bitwy_scenariusze (+ _strony, _jednostki, _klucze, _wyzwalacze) — scenariusze bitew
-- Stan bitwy (wypełnia silnik): bitwy_jednostki, bitwy_sekcje, bitwy_systemy, bitwy_zyly, bitwy_klucze, bitwy_piloci,
--   bitwy_stanowiska, bitwy_blokady, bitwy_rozkazy, bitwy_zdarzenia, bitwy_migawki, bitwy_xp.
-- Żadnego JSON: żyły osłon i baterii jako mapy bitowe / bajty (VARBINARY), migawki jako zrzut binarny.
--
-- Zmiany w istniejących tabelach: mapa_bitwy (rodzaj, scenariusz, zegar), mapa_piloci.xp → DECIMAL(10,1)
-- (0,5 XP za akcję w symulacji), mapa_obiekty.profil_klasy.
--
-- Wymaga migracji 010 (mapa_bitwy), 067 (mapa_piloci). Import w phpMyAdmin. Ponowny import: ALTER zgłosi
-- „Duplicate column” — tabele są już w bazie.

SET NAMES utf8mb4;

-- ---------------------------------------------------------------------------------------------------------------
-- Słowniki mechaniki
-- ---------------------------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS mechanika_stale (
  kod VARCHAR(40) NOT NULL PRIMARY KEY,
  wartosc DOUBLE NOT NULL,
  status ENUM('ustalone','robocze','propozycja') NOT NULL DEFAULT 'robocze',
  opis VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profile_klas (
  kod VARCHAR(20) NOT NULL PRIMARY KEY,
  nazwa VARCHAR(160) NOT NULL,
  dlugosc_m DECIMAL(8,1) NOT NULL,
  moc_reaktora_w DOUBLE NOT NULL,
  utrata_rdzenia VARCHAR(255) NULL,
  generatory_oslon TINYINT UNSIGNED NOT NULL,
  zyly_oslon SMALLINT UNSIGNED NOT NULL,
  zapasowy_zyly SMALLINT UNSIGNED NULL,
  siatka_kolumny SMALLINT UNSIGNED NULL,
  siatka_wiersze SMALLINT UNSIGNED NULL,
  zyla_u0_v DECIMAL(8,3) NOT NULL,
  zyla_r0_ohm DECIMAL(8,3) NOT NULL,
  oslony_domyslnie_hz SMALLINT UNSIGNED NOT NULL,
  po_utracie_generatora VARCHAR(500) NULL,
  ekran_zyl VARCHAR(160) NULL,
  baterie TINYINT UNSIGNED NOT NULL DEFAULT 0,
  lufy_na_baterie TINYINT UNSIGNED NOT NULL DEFAULT 0,
  zyly_baterii SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  ladowanie_tiki TINYINT UNSIGNED NOT NULL DEFAULT 6,
  przydzial_baterii DECIMAL(4,3) NOT NULL DEFAULT 0,
  obrona_punktowa SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  mysliwce SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  silniki_glowne TINYINT UNSIGNED NULL,
  silniki_manewrowe TINYINT UNSIGNED NULL,
  obrot_deg_na_min DECIMAL(6,2) NULL,
  predkosc_km_s DECIMAL(6,3) NOT NULL,
  status ENUM('ustalony','roboczy','propozycja') NOT NULL DEFAULT 'roboczy',
  zmieniono TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profile_klas_jednostki (
  profil_kod VARCHAR(20) NOT NULL,
  nr TINYINT UNSIGNED NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  rola ENUM('rdzen','dystrybucja','pomocniczy','zapasowy','zasobnik') NOT NULL,
  PRIMARY KEY (profil_kod, nr),
  FOREIGN KEY (profil_kod) REFERENCES profile_klas (kod) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS profile_klas_sektory (
  profil_kod VARCHAR(20) NOT NULL,
  nr TINYINT UNSIGNED NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  PRIMARY KEY (profil_kod, nr),
  FOREIGN KEY (profil_kod) REFERENCES profile_klas (kod) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Sekcje kadłuba (W13): integralność 0–100 z progami 75 / 50 / 25; udział = waga w średniej kadłuba.
CREATE TABLE IF NOT EXISTS profile_klas_kadlub (
  profil_kod VARCHAR(20) NOT NULL,
  sekcja VARCHAR(40) NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  udzial DECIMAL(4,3) NOT NULL,
  PRIMARY KEY (profil_kod, sekcja),
  FOREIGN KEY (profil_kod) REFERENCES profile_klas (kod) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS typy_maszyn (
  kod VARCHAR(20) NOT NULL PRIMARY KEY,
  nazwa VARCHAR(120) NOT NULL,
  strona VARCHAR(40) NOT NULL,
  rola VARCHAR(80) NOT NULL,
  hz_bazowe SMALLINT UNSIGNED NOT NULL,
  oslona_hz SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  predkosc_km_s DECIMAL(5,3) NOT NULL,
  przekroj_m2 DECIMAL(7,1) NOT NULL,
  energia_strzalu_j DOUBLE NOT NULL,
  ladowanie_tiki TINYINT UNSIGNED NOT NULL DEFAULT 1,
  status ENUM('ustalony','roboczy','propozycja') NOT NULL DEFAULT 'propozycja',
  opis VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Czas wykonania rozkazów (MECHANIKA 1.1). dzialanie_s NULL = działa do następnej zmiany.
-- theta_mn — mnożnik rozrzutu strzałów W tę jednostkę (unik), theta_wlasna_mn — rozrzut WŁASNYCH strzałów (<1 celniej).
CREATE TABLE IF NOT EXISTS rozkazy_profile (
  kod VARCHAR(30) NOT NULL PRIMARY KEY,
  nazwa VARCHAR(120) NOT NULL,
  grupa ENUM('kurs','unik','as','zawrot','szyk','walka','rozkaz_klucza','okret') NOT NULL,
  przygotowanie_s DECIMAL(5,1) NOT NULL,
  dzialanie_s DECIMAL(6,1) NULL,
  odnowienie_s DECIMAL(6,1) NOT NULL DEFAULT 0,
  theta_mn DECIMAL(4,2) NULL,
  theta_wlasna_mn DECIMAL(4,2) NULL,
  predkosc_mn DECIMAL(4,2) NULL,
  ogien_wylaczony TINYINT(1) NOT NULL DEFAULT 0,
  ranga_min ENUM('kadet','standard','as') NOT NULL DEFAULT 'kadet',
  ranga_skraca TINYINT(1) NOT NULL DEFAULT 0,
  opis VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------------------------------------------
-- Scenariusze
-- ---------------------------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS bitwy_scenariusze (
  kod VARCHAR(40) NOT NULL PRIMARY KEY,
  nazwa VARCHAR(160) NOT NULL,
  odprawa TEXT NOT NULL,
  opis_mg TEXT NULL,
  okno_s INT UNSIGNED NOT NULL,
  pole_km INT UNSIGNED NOT NULL DEFAULT 200,
  zwyciestwo VARCHAR(500) NOT NULL,
  porazka VARCHAR(500) NOT NULL,
  status ENUM('roboczy','gotowy','wycofany') NOT NULL DEFAULT 'roboczy',
  zmieniono TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bitwy_scenariusze_strony (
  scenariusz_kod VARCHAR(40) NOT NULL,
  strona VARCHAR(120) NOT NULL,
  kolor CHAR(7) NOT NULL,
  dowodzenie ENUM('gracze','radus','ackbar','calrissian') NOT NULL,
  rola ENUM('obrona','atak') NOT NULL,
  asy_proc TINYINT UNSIGNED NOT NULL DEFAULT 5,
  kadeci_proc TINYINT UNSIGNED NOT NULL DEFAULT 35,
  PRIMARY KEY (scenariusz_kod, strona),
  FOREIGN KEY (scenariusz_kod) REFERENCES bitwy_scenariusze (kod) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- z_mapy = 1: przy tworzeniu symulacji MG wskazuje jednostkę z mapy tej klasy (np. Walako); 0: jednostka wirtualna.
CREATE TABLE IF NOT EXISTS bitwy_scenariusze_jednostki (
  scenariusz_kod VARCHAR(40) NOT NULL,
  nr TINYINT UNSIGNED NOT NULL,
  strona VARCHAR(120) NOT NULL,
  profil_kod VARCHAR(20) NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  z_mapy TINYINT(1) NOT NULL DEFAULT 0,
  x_km DECIMAL(10,2) NOT NULL,
  y_km DECIMAL(10,2) NOT NULL,
  kurs_deg DECIMAL(6,2) NOT NULL DEFAULT 0,
  predkosc_km_s DECIMAL(6,3) NOT NULL DEFAULT 0,
  kadlub TINYINT UNSIGNED NOT NULL DEFAULT 100,
  wejscie_s INT UNSIGNED NOT NULL DEFAULT 0,
  wejscie_rozrzut_s INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (scenariusz_kod, nr),
  FOREIGN KEY (scenariusz_kod, strona) REFERENCES bitwy_scenariusze_strony (scenariusz_kod, strona) ON DELETE CASCADE,
  FOREIGN KEY (profil_kod) REFERENCES profile_klas (kod)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Fale kluczy: jednostka_nr = okręt macierzysty (NULL: klucze z zewnątrz, np. wyjście ze skoku), start_s — wyjście
-- z hangaru pierwszego klucza fali, rozrzut losowany z ziarna bitwy. Pozycja startu dla kluczy z zewnątrz: x_km, y_km.
CREATE TABLE IF NOT EXISTS bitwy_scenariusze_klucze (
  scenariusz_kod VARCHAR(40) NOT NULL,
  fala TINYINT UNSIGNED NOT NULL,
  strona VARCHAR(120) NOT NULL,
  jednostka_nr TINYINT UNSIGNED NULL,
  typ_maszyny VARCHAR(20) NOT NULL,
  liczba_kluczy TINYINT UNSIGNED NOT NULL,
  start_s INT UNSIGNED NOT NULL DEFAULT 0,
  start_rozrzut_s INT UNSIGNED NOT NULL DEFAULT 0,
  x_km DECIMAL(10,2) NULL,
  y_km DECIMAL(10,2) NULL,
  rozkaz VARCHAR(30) NOT NULL DEFAULT 'patrol',
  PRIMARY KEY (scenariusz_kod, fala, strona, typ_maszyny),
  FOREIGN KEY (scenariusz_kod, strona) REFERENCES bitwy_scenariusze_strony (scenariusz_kod, strona) ON DELETE CASCADE,
  FOREIGN KEY (typ_maszyny) REFERENCES typy_maszyn (kod),
  FOREIGN KEY (rozkaz) REFERENCES rozkazy_profile (kod)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bitwy_scenariusze_wyzwalacze (
  scenariusz_kod VARCHAR(40) NOT NULL,
  nr TINYINT UNSIGNED NOT NULL,
  czas_s INT UNSIGNED NOT NULL,
  rozrzut_s INT UNSIGNED NOT NULL DEFAULT 0,
  rodzaj ENUM('komunikat','posilki','koniec') NOT NULL,
  tresc VARCHAR(500) NOT NULL,
  PRIMARY KEY (scenariusz_kod, nr),
  FOREIGN KEY (scenariusz_kod) REFERENCES bitwy_scenariusze (kod) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------------------------------------------------
-- Istniejące tabele
-- ---------------------------------------------------------------------------------------------------------------

-- Zegar bitwy: czas bitwy = (teraz − zegar_start_utc) − zegar_pauzy_s − (pauza trwa ? teraz − pauza_od_utc : 0).
-- Pauza i cofnięcie tylko dla MG (symulacja); bitwa rzeczywista płynie 1:1 bez pauzy.
ALTER TABLE mapa_bitwy
  MODIFY planeta_id INT UNSIGNED NULL,
  MODIFY status ENUM('przygotowanie','aktywna','zakonczona','anulowana') NOT NULL DEFAULT 'aktywna',
  ADD COLUMN rodzaj ENUM('rzeczywista','symulacja') NOT NULL DEFAULT 'rzeczywista' AFTER nazwa,
  ADD COLUMN scenariusz_kod VARCHAR(40) NULL AFTER rodzaj,
  ADD COLUMN ziarno INT UNSIGNED NOT NULL DEFAULT 0 AFTER scenariusz_kod,
  ADD COLUMN zegar_start_utc DATETIME(3) NULL AFTER ziarno,
  ADD COLUMN zegar_pauzy_s DECIMAL(12,3) NOT NULL DEFAULT 0 AFTER zegar_start_utc,
  ADD COLUMN pauza_od_utc DATETIME(3) NULL AFTER zegar_pauzy_s,
  ADD COLUMN tik_policzony INT UNSIGNED NOT NULL DEFAULT 0 AFTER pauza_od_utc,
  ADD COLUMN kotwica_x DECIMAL(14,1) NULL AFTER tik_policzony,
  ADD COLUMN kotwica_y DECIMAL(14,1) NULL AFTER kotwica_x,
  ADD COLUMN prowadzacy_login VARCHAR(64) NULL AFTER kotwica_y,
  ADD KEY ix_mapa_bitwy_rodzaj (rodzaj, status),
  ADD CONSTRAINT fk_mapa_bitwy_scenariusz FOREIGN KEY (scenariusz_kod) REFERENCES bitwy_scenariusze (kod);

ALTER TABLE mapa_piloci MODIFY xp DECIMAL(10,1) NOT NULL DEFAULT 0;

ALTER TABLE mapa_obiekty
  ADD COLUMN profil_klasy VARCHAR(20) NULL,
  ADD CONSTRAINT fk_mapa_obiekty_profil FOREIGN KEY (profil_klasy) REFERENCES profile_klas (kod);

-- ---------------------------------------------------------------------------------------------------------------
-- Stan bitwy (silnik)
-- ---------------------------------------------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS bitwy_jednostki (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_id BIGINT UNSIGNED NOT NULL,
  obiekt_id BIGINT UNSIGNED NULL,
  profil_kod VARCHAR(20) NOT NULL,
  nazwa VARCHAR(160) NOT NULL,
  strona VARCHAR(120) NOT NULL,
  scenariusz_nr TINYINT UNSIGNED NULL,
  stan ENUM('oczekuje','w_bitwie','wycofana','unieszkodliwiona','zniszczona') NOT NULL DEFAULT 'oczekuje',
  wejscie_tik INT UNSIGNED NOT NULL DEFAULT 0,
  x_km DECIMAL(12,3) NOT NULL DEFAULT 0,
  y_km DECIMAL(12,3) NOT NULL DEFAULT 0,
  vx_km_s DECIMAL(10,5) NOT NULL DEFAULT 0,
  vy_km_s DECIMAL(10,5) NOT NULL DEFAULT 0,
  zwrot_deg DECIMAL(8,3) NOT NULL DEFAULT 0,
  omega_deg_s DECIMAL(8,4) NOT NULL DEFAULT 0,
  kadlub_start TINYINT UNSIGNED NOT NULL DEFAULT 100,
  dlawienie DECIMAL(4,3) NOT NULL DEFAULT 1,
  margines_cieplny DECIMAL(7,3) NOT NULL DEFAULT 100,
  zasobnik_porcje DECIMAL(8,3) NOT NULL DEFAULT 0,
  KEY ix_bitwy_jednostki (bitwa_id, strona),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE,
  FOREIGN KEY (obiekt_id) REFERENCES mapa_obiekty (id) ON DELETE SET NULL,
  FOREIGN KEY (profil_kod) REFERENCES profile_klas (kod)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bitwy_sekcje (
  bitwa_jednostka_id BIGINT UNSIGNED NOT NULL,
  sekcja VARCHAR(40) NOT NULL,
  integralnosc DECIMAL(5,2) NOT NULL DEFAULT 100,
  PRIMARY KEY (bitwa_jednostka_id, sekcja),
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- System okrętu w bitwie: generator osłon, bateria, rdzeń, silnik, sensory… (kod np. oslona_L, bateria_P3, rdzen_2).
CREATE TABLE IF NOT EXISTS bitwy_systemy (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_jednostka_id BIGINT UNSIGNED NOT NULL,
  kod VARCHAR(40) NOT NULL,
  stan ENUM('gotowy','przestrajanie','przeciazony','uszkodzony','wylaczony','zniszczony') NOT NULL DEFAULT 'gotowy',
  hz_zadane SMALLINT UNSIGNED NULL,
  hz_osiagane SMALLINT UNSIGNED NULL,
  hz_min SMALLINT UNSIGNED NULL,
  hz_max SMALLINT UNSIGNED NULL,
  przydzial_porcji DECIMAL(7,3) NOT NULL DEFAULT 0,
  ladunek DECIMAL(5,4) NOT NULL DEFAULT 0,
  obciazenie_j DOUBLE NOT NULL DEFAULT 0,
  rykoszet_j DOUBLE NOT NULL DEFAULT 0,
  temperatura DECIMAL(8,3) NOT NULL DEFAULT 0,
  UNIQUE KEY uq_bitwy_systemy (bitwa_jednostka_id, kod),
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Żyły generatora lub baterii: martwe — mapa bitowa (bit n = żyła n+1 martwa; 3600 żył = 450 B),
-- temperatury — 1 bajt na żyłę (0–255 = 0–51 °C umownych, żyła ginie powyżej 40).
CREATE TABLE IF NOT EXISTS bitwy_zyly (
  system_id BIGINT UNSIGNED NOT NULL PRIMARY KEY,
  liczba SMALLINT UNSIGNED NOT NULL,
  martwe VARBINARY(1024) NOT NULL,
  temperatury VARBINARY(4096) NOT NULL,
  FOREIGN KEY (system_id) REFERENCES bitwy_systemy (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Klucz w bitwie. Stan lampy (PULPITY 1b): hangar (odlicza do start_tik) → gotowy → w_locie → powrot → stracony.
CREATE TABLE IF NOT EXISTS bitwy_klucze (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_id BIGINT UNSIGNED NOT NULL,
  strona VARCHAR(120) NOT NULL,
  macierzysta_id BIGINT UNSIGNED NULL,
  mapa_klucz_id INT NULL,
  numer SMALLINT UNSIGNED NOT NULL,
  typ_maszyny VARCHAR(20) NOT NULL,
  maszyny TINYINT UNSIGNED NOT NULL DEFAULT 4,
  stan ENUM('hangar','gotowy','w_locie','powrot','stracony') NOT NULL DEFAULT 'hangar',
  start_tik INT UNSIGNED NULL,
  hz_bazowe SMALLINT UNSIGNED NOT NULL,
  moc DECIMAL(4,3) NOT NULL DEFAULT 0,
  figura VARCHAR(30) NULL,
  figura_od_tik INT UNSIGNED NULL,
  zmiany_w_cyklu TINYINT UNSIGNED NOT NULL DEFAULT 0,
  cykl_nr INT UNSIGNED NOT NULL DEFAULT 0,
  rozkaz VARCHAR(30) NULL,
  cel_jednostka_id BIGINT UNSIGNED NULL,
  cel_klucz_id BIGINT UNSIGNED NULL,
  x_km DECIMAL(12,3) NOT NULL DEFAULT 0,
  y_km DECIMAL(12,3) NOT NULL DEFAULT 0,
  vx_km_s DECIMAL(10,5) NOT NULL DEFAULT 0,
  vy_km_s DECIMAL(10,5) NOT NULL DEFAULT 0,
  UNIQUE KEY uq_bitwy_klucze (bitwa_id, strona, numer),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE,
  FOREIGN KEY (macierzysta_id) REFERENCES bitwy_jednostki (id) ON DELETE SET NULL,
  FOREIGN KEY (typ_maszyny) REFERENCES typy_maszyn (kod),
  FOREIGN KEY (figura) REFERENCES rozkazy_profile (kod),
  FOREIGN KEY (rozkaz) REFERENCES rozkazy_profile (kod)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Pilot w kluczu bitwy: z mapa_piloci (pilot_id) albo wirtualny (pilot_id NULL, np. rebelianci w symulacji).
CREATE TABLE IF NOT EXISTS bitwy_piloci (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_klucz_id BIGINT UNSIGNED NOT NULL,
  pilot_id INT NULL,
  imie VARCHAR(160) NOT NULL,
  ranga ENUM('as','standard','kadet') NOT NULL,
  stan ENUM('w_kluczu','zestrzelony','uratowany') NOT NULL DEFAULT 'w_kluczu',
  akcje INT UNSIGNED NOT NULL DEFAULT 0,
  KEY ix_bitwy_piloci_pilot (pilot_id),
  FOREIGN KEY (bitwa_klucz_id) REFERENCES bitwy_klucze (id) ON DELETE CASCADE,
  FOREIGN KEY (pilot_id) REFERENCES mapa_piloci (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bitwy_stanowiska (
  bitwa_jednostka_id BIGINT UNSIGNED NOT NULL,
  pulpit VARCHAR(40) NOT NULL,
  login VARCHAR(64) NULL,
  PRIMARY KEY (bitwa_jednostka_id, pulpit),
  KEY ix_bitwy_stanowiska_login (login),
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Blokady kapitana i przyciski obowiązkowe (PULPITY 4); element = tekst lub id gniazda pulpitu.
CREATE TABLE IF NOT EXISTS bitwy_blokady (
  bitwa_jednostka_id BIGINT UNSIGNED NOT NULL,
  pulpit VARCHAR(40) NOT NULL,
  element VARCHAR(120) NOT NULL,
  poziom ENUM('obligatoryjny','dostepny','zablokowany') NOT NULL,
  login VARCHAR(64) NULL,
  PRIMARY KEY (bitwa_jednostka_id, pulpit, element),
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dziennik rozkazów (wejścia silnika). uid — identyfikator nadany przez konsolę: ponowiona wysyłka nie tworzy
-- drugiego rozkazu. odebrano_utc — czas serwera (komputera centralnego); od niego liczy się czas wykonania.
CREATE TABLE IF NOT EXISTS bitwy_rozkazy (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_id BIGINT UNSIGNED NOT NULL,
  uid CHAR(36) NOT NULL,
  odebrano_utc DATETIME(3) NOT NULL,
  tik INT UNSIGNED NOT NULL,
  login VARCHAR(64) NULL,
  ai TINYINT(1) NOT NULL DEFAULT 0,
  bitwa_jednostka_id BIGINT UNSIGNED NULL,
  bitwa_klucz_id BIGINT UNSIGNED NULL,
  pulpit VARCHAR(40) NULL,
  system_kod VARCHAR(40) NULL,
  rozkaz_kod VARCHAR(30) NULL,
  parametr VARCHAR(60) NULL,
  wartosc_przed VARCHAR(60) NULL,
  wartosc_po VARCHAR(60) NULL,
  przyczyna VARCHAR(255) NULL,
  stan ENUM('przygotowanie','dziala','zakonczony','przerwany') NOT NULL DEFAULT 'przygotowanie',
  dziala_od_tik INT UNSIGNED NULL,
  dziala_do_tik INT UNSIGNED NULL,
  odnowienie_do_tik INT UNSIGNED NULL,
  przerwany_przez BIGINT UNSIGNED NULL,
  UNIQUE KEY uq_bitwy_rozkazy_uid (bitwa_id, uid),
  KEY ix_bitwy_rozkazy_tik (bitwa_id, tik),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE,
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE,
  FOREIGN KEY (bitwa_klucz_id) REFERENCES bitwy_klucze (id) ON DELETE CASCADE,
  FOREIGN KEY (rozkaz_kod) REFERENCES rozkazy_profile (kod)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bitwy_zdarzenia (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  bitwa_id BIGINT UNSIGNED NOT NULL,
  tik INT UNSIGNED NOT NULL,
  rodzaj VARCHAR(40) NOT NULL,
  sprawca_jednostka_id BIGINT UNSIGNED NULL,
  sprawca_klucz_id BIGINT UNSIGNED NULL,
  cel_jednostka_id BIGINT UNSIGNED NULL,
  cel_klucz_id BIGINT UNSIGNED NULL,
  wartosc DOUBLE NULL,
  opis VARCHAR(255) NULL,
  KEY ix_bitwy_zdarzenia_tik (bitwa_id, tik),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Migawka stanu co cykl lub minutę — do cofnięcia przez MG (zrzut binarny tabel bitwy, nie JSON).
CREATE TABLE IF NOT EXISTS bitwy_migawki (
  bitwa_id BIGINT UNSIGNED NOT NULL,
  tik INT UNSIGNED NOT NULL,
  dane LONGBLOB NOT NULL,
  PRIMARY KEY (bitwa_id, tik),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- XP pilotów z bitwy: symulacja — 0,5 za akcję × mnożnik rangi (as 0,5, standardowy 1, kadet 1,5);
-- trafia do mapa_piloci.xp po zatwierdzeniu przez MG (zatwierdzono_utc).
CREATE TABLE IF NOT EXISTS bitwy_xp (
  bitwa_id BIGINT UNSIGNED NOT NULL,
  pilot_id INT NOT NULL,
  akcje INT UNSIGNED NOT NULL DEFAULT 0,
  xp_surowe DECIMAL(8,1) NOT NULL DEFAULT 0,
  mnoznik DECIMAL(3,2) NOT NULL DEFAULT 1,
  xp DECIMAL(8,1) NOT NULL DEFAULT 0,
  zatwierdzono_utc DATETIME NULL,
  zatwierdzil_login VARCHAR(64) NULL,
  PRIMARY KEY (bitwa_id, pilot_id),
  FOREIGN KEY (bitwa_id) REFERENCES mapa_bitwy (id) ON DELETE CASCADE,
  FOREIGN KEY (pilot_id) REFERENCES mapa_piloci (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

VALUES ('v068-bitwy-symulacje', 'Bitwy i symulacje bitew: słowniki mechaniki, profile klas, scenariusze, stan bitwy, XP pilotów DECIMAL')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

