  ADD COLUMN zasieg_ognia_km DECIMAL(5,2) NOT NULL DEFAULT 1.5 AFTER zwrot_deg_s,
  ADD COLUMN stozek_deg DECIMAL(5,1) NOT NULL DEFAULT 15 AFTER zasieg_ognia_km,
