UPDATE typy_maszyn SET zwrot_deg_s = 18, zasieg_ognia_km = 1.2, stozek_deg = 10, theta_mrad = 5 WHERE kod = 'TIE_SA';
UPDATE typy_maszyn SET zwrot_deg_s = 10, zasieg_ognia_km = 1, stozek_deg = 20, theta_mrad = 6 WHERE kod = 'LAMBDA';
UPDATE typy_maszyn SET zwrot_deg_s = 28, zasieg_ognia_km = 1.6, stozek_deg = 15, theta_mrad = 3.5 WHERE kod = 'X_WING';
UPDATE typy_maszyn SET zwrot_deg_s = 18, zasieg_ognia_km = 1.4, stozek_deg = 15, theta_mrad = 4.5 WHERE kod = 'Y_WING';
UPDATE typy_maszyn SET zwrot_deg_s = 45, zasieg_ognia_km = 1.5, stozek_deg = 15, theta_mrad = 4 WHERE kod = 'A_WING';
UPDATE typy_maszyn SET zwrot_deg_s = 20, zasieg_ognia_km = 1.6, stozek_deg = 15, theta_mrad = 4 WHERE kod = 'B_WING';

DELETE FROM profile_klas_uzbrojenie WHERE profil_kod IN ('ISD_I', 'MC80');

VALUES ('v075-mostek-dane-walka', 'Dane walki: kinematyka i broń maszyn, uzbrojenie okrętów na kadłubie')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/076_ster_okretu.sql
-- =====================================================================

-- Ster okrętu gracza i cel wskazany baterii (konsole Silniki, Nawigacja, Kontrola ognia):
-- kurs_cel_deg / v_cel_km_s — kurs i prędkość zadane rozkazem „ster” (okręt skręca z prędkością obrotu profilu
-- i przyspiesza do zadanej), cel_ognia_nr — numer wrogiej jednostki ze scenariusza wskazanej bateriom.
-- Wymaga 070. Import w phpMyAdmin. Ponowny import: ALTER zgłosi „Duplicate column” — kolumny już są.

SET NAMES utf8mb4;

ALTER TABLE bitwy_jednostki
  ADD COLUMN kurs_cel_deg DOUBLE NULL AFTER zwrot_deg,
  ADD COLUMN v_cel_km_s DOUBLE NULL AFTER kurs_cel_deg,
  ADD COLUMN cel_ognia_nr TINYINT UNSIGNED NULL AFTER v_cel_km_s;

VALUES ('v076-bitwy-ster-okretu', 'Ster okrętu gracza i cel wskazany baterii w symulacjach bitew')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/077_stale_stanowiska.sql
-- =====================================================================

-- Stałe stanowiska na mostku (narzedzia/mostek/PULPITY.md 1c): pulpit okrętu przypisany graczowi na stałe, niezależnie
-- od symulacji. Każda nowa symulacja okrętu dostaje kopię tych przydziałów (bitwy_stanowiska), a zmiana stałego
-- przydziału przechodzi też na trwające symulacje tego okrętu. Przydziela MG albo kapitan (api/bitwa.php, mostek_stanowisko).
-- Pulpit: nazwa pulpitu klasy ('Osłony', 'Radar', …) albo 'Klucz N' / 'Eskadra N'.

CREATE TABLE IF NOT EXISTS okrety_stanowiska (
  obiekt_id BIGINT UNSIGNED NOT NULL,
  pulpit VARCHAR(40) NOT NULL,
  login VARCHAR(64) NOT NULL,
  przydzielil VARCHAR(64) NULL,
  zmieniono_utc DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (obiekt_id, pulpit),
  KEY ix_okrety_stanowiska_login (login),
  FOREIGN KEY (obiekt_id) REFERENCES mapa_obiekty (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

VALUES ('v077-stale-stanowiska', 'Stałe stanowiska graczy na mostku okrętu i mostek bez symulacji')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/078_nastawy_oslon_reaktorow.sql
-- =====================================================================

-- Nastawy konsol Osłony i Reaktory w symulacjach (narzedzia/mostek/MECHANIKA.md 11.4): suwaki 0…1 i przełączniki
-- (pokrycie granic sektorów osłon, synchronizacje, przydziały mocy, moc reaktorów pomocniczych, gęstość hipermaterii,
-- pole komory, rezerwy, zakresy reaktora uzbrojenia i generatora mocy, przełączenia zasilania). Brak wiersza = wartość
-- domyślna z silnika (BITWA_NASTAWY). Ciepło rdzenia i dławienie — stan okrętu w symulacji.
-- Rozkazy (bitwy_rozkazy): nastawa / synchronizuj / przelacz (wartosc_po „kod=liczba”), wyrownaj (grupa), wzmocnij.
-- Wymaga 068 i odświeżonej 069 (rozkaz „nastawa”). Kolumna dławienia rdzenia to dlawienie_rdzenia — „dlawienie”
-- (DECIMAL, współczynnik) istnieje od 068 i nie jest używana przez silnik.

CREATE TABLE IF NOT EXISTS bitwy_nastawy (
  bitwa_jednostka_id BIGINT UNSIGNED NOT NULL,
  kod VARCHAR(24) NOT NULL,
  wartosc DOUBLE NOT NULL,
  PRIMARY KEY (bitwa_jednostka_id, kod),
  FOREIGN KEY (bitwa_jednostka_id) REFERENCES bitwy_jednostki (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE bitwy_jednostki
  ADD COLUMN cieplo_reaktora DOUBLE NOT NULL DEFAULT 0,
  ADD COLUMN dlawienie_rdzenia TINYINT(1) NOT NULL DEFAULT 0;

VALUES ('v078-nastawy-oslon-reaktorow', 'Nastawy konsol Osłony i Reaktory, ciepło rdzenia w symulacjach bitew')
ON DUPLICATE KEY UPDATE opis = VALUES(opis);

-- =====================================================================
-- migracje/079_galactic_center_czarna_dziura.sql
-- =====================================================================

-- Galactic Center (0, -2131.4) jest środkiem galaktyki i centralną czarną dziurą.
-- Wiersz mapa_planety pozostaje kotwicą układu/nawigacji; nie reprezentuje planety.

SET NAMES utf8mb4;

ALTER TABLE mapa_planety
  ADD COLUMN typ_ciala ENUM('planeta','czarna_dziura') NOT NULL DEFAULT 'planeta' AFTER nazwa;

ALTER TABLE planety_cykle
  MODIFY COLUMN gwiazda_typ ENUM('O','B','A','F','G','K','M','WD','RG','BH') NULL AFTER srednica_km;

UPDATE mapa_planety
SET typ_ciala='czarna_dziura', grawitacja=0, slonca=0, ksiezyce=0, doba=0, rok=0, srednica=0
WHERE nazwa='Galactic Center' AND x=0 AND y=-2131.4;

SELECT id, 'BH', NULL, NULL, NULL, NULL FROM mapa_planety
WHERE nazwa='Galactic Center' AND x=0 AND y=-2131.4
ON DUPLICATE KEY UPDATE gwiazda_typ='BH', doba_h=NULL, rok_dni=NULL, srednica_km=NULL, promien_orbity_au=NULL;

DELETE k FROM planety_ksiezyce k JOIN mapa_planety p ON p.id=k.planeta_id
WHERE p.nazwa='Galactic Center' AND p.x=0 AND p.y=-2131.4;

VALUES ('v079-galactic-center-czarna-dziura', 'Galactic Center jako środek gwiazd tła i czarna dziura bez planet ani księżyców')
ON DUPLICATE KEY UPDATE opis=VALUES(opis);
